     1→/**
     2→ * L6 审计层：智能问数全链路审计日志。
     3→ * 成功、降级、错误与被拒绝（输入/权限/频率/开关）的请求全部落账，
     4→ * 写入失败仅告警不阻塞主流程（审计不应成为可用性瓶颈）。
     5→ */
     6→import { getPool } from './db';
     7→
     8→export type AuditStatus =
     9→  | 'SUCCESS'
    10→  | 'CACHE'
    11→  | 'FALLBACK'
    12→  | 'ERROR'
    13→  | 'CLARIFY'
    14→  | 'REFUSED'
    15→  | 'DENIED_INPUT'
    16→  | 'DENIED_AUTH'
    17→  | 'DENIED_RATE'
    18→  | 'DENIED_SWITCH';
    19→
    20→export interface AuditEntry {
    21→  userId: number;
    22→  username: string;
    23→  endpoint: 'query' | 'report' | 'query_report' | 'report_template';
    24→  dataSourceId?: string;
    25→  question?: string;
    26→  status: AuditStatus;
    27→  detail?: string;
    28→  /** 真实执行的 SQL（P0 双阶段模式）；-1 行数表示未执行 */
    29→  executedSql?: string;
    30→  rowCount?: number;
    31→  durationMs?: number;
    32→}
    33→
    34→export function writeAudit(entry: AuditEntry): void {
    35→  getPool()
    36→    .query(
    37→      `INSERT INTO query_audit_log
    38→        (user_id, username, endpoint, data_source_id, question, status, detail, executed_sql, row_count, duration_ms)
    39→       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    40→      [
    41→        entry.userId,
    42→        entry.username,
    43→        entry.endpoint,
    44→        (entry.dataSourceId || '').slice(0, 64),
    45→        (entry.question || '').slice(0, 500),
    46→        entry.status,
    47→        (entry.detail || '').slice(0, 255),
    48→        (entry.executedSql || '').slice(0, 2000),
    49→        entry.rowCount === undefined ? -1 : Math.round(entry.rowCount),
    50→        Math.max(0, Math.round(entry.durationMs || 0)),
    51→      ]
    52→    )
    53→    .catch((err) => {
    54→      console.warn('[Audit] 审计日志写入失败:', err?.message || err);
    55→    });
    56→}
