    31→const SAMPLE_ROWS_FOR_LLM = 15;
    32→export const VALID_STAGE1_CHARTS = ['bar', 'line', 'area', 'pie', 'donut', 'radar', 'scatter', 'treemap', 'heatmap'] as const;
    33→
    34→/** 问数金额单位选项：用户问数前自选，SQL 生成时按除数换算（divisor=元为原值） */
    35→export const AMOUNT_UNIT_OPTIONS: Record<string, { label: string; divisor: number; suffix: string }> = {
    36→  '亿元': { label: '亿元', divisor: 100000000, suffix: 'yi' },
    37→  '百万元': { label: '百万元', divisor: 1000000, suffix: 'baiwan' },
    38→  '万元': { label: '万元', divisor: 10000, suffix: 'wan' },
