    41→
    42→/** 金额单位白名单归一：非白名单值返回 undefined（不注入约定，保持原值口径） */
    43→export function normalizeAmountUnit(v: unknown): string | undefined {
    44→  const s = String(v || '').trim();
    45→  return AMOUNT_UNIT_OPTIONS[s] ? s : undefined;
    46→}
    47→
    48→/** 金额单位 prompt 约定：拼在阶段一用户消息首位，指令 SQL 对金额列统一除以除数并带单位后缀；v0.5.2 起导出供报表链路复用 */
    49→export function buildAmountUnitPrompt(unit?: string): string {
