    79→  traceId: string;
    80→  /** 金额输出单位（亿元/百万元/万元/元）：阶段一 SQL 生成按除数换算，白名单外不生效 */
    81→  amountUnit?: string;
    82→}
    83→
    84→export interface LiveQuerySuccess {
