   507→export async function runLiveQuery(input: LiveQueryInput): Promise<LiveQueryOutcome> {
   508→  const { query, history, schema, guidance, dataSourceId, dsType, sensitiveRemoved } = input;
   509→  const trace = (step: TraceStep) => {
   510→    try {
   511→      input.onTrace?.(step);
   512→    } catch {
   513→      // 留痕失败不阻断主链路
   514→    }
   515→  };
   516→  const t0 = Date.now();
   517→  input.onStage?.('understanding');
   518→  // M2 计划模式：已批准计划先留痕，阶段一按其步骤引导生成（并跳过歧义澄清）
   519→  if (input.approvedPlan) {
   520→    trace({
   521→      stepType: 'plan',
   522→      title: '按已批准计划执行',
   523→      inputSummary: input.approvedPlan.understanding,
   524→      outputSummary: `${input.approvedPlan.steps.length} 个步骤：${input.approvedPlan.steps.map((s) => s.title).join(' → ')}`,
   525→      durationMs: Date.now() - t0,
   526→    });
   527→  }
   528→  // Schema Linking（借鉴 Chat2DB AI 数据集）：大 schema 时只把相关表注入 prompt（P2-9 关键词粗排 + embedding 精排）；
   529→  // 安全白名单（executeSafeSql）仍用全量 schema，召回遗漏不会误杀合法 SQL
   530→  const promptSchema = await selectRelevantTablesAsync(schema, query);
   531→  trace({
   532→    stepType: 'linking',
   533→    title: 'Schema 圈表：选定相关表',
   534→    inputSummary: query,
   535→    outputSummary: `命中 ${promptSchema.length}/${Array.isArray(schema) ? schema.length : 0} 张表：${promptSchema.map((t: any) => String(t?.name || '')).join(', ')}`,
   536→    durationMs: Date.now() - t0,
   537→  });
   538→  // 上下文构建并行化：few-shot / 知识库 RAG / 外部知识库 / 语义指标 / 点踩反例 / 个人对话沉淀六者互不依赖，并发执行（各自失败不阻断）
   539→  const [fewShotPairs, knowledgeRaw, externalKb, metricHits, negativePairs, convPairs] = await Promise.all([
   540→    // P0 Few-shot（DAIL-SQL 双维度）：用圈定表名引导样例贴近当前可查表
   541→    loadFewShotExamples(
   542→      dataSourceId,
   543→      query,
