   127→/** mysql2 将 DECIMAL/聚合值返回为字符串；把可安全转换的列统一转为 number，便于图表与统计 */
   128→export function coerceNumericColumns(rows: Record<string, any>[]): Record<string, any>[] {
   129→  if (rows.length === 0) return rows;
   130→  const cols = Object.keys(rows[0]);
   131→  const numericCols = cols.filter((c) => {
   132→    let seen = 0;
   133→    for (const r of rows.slice(0, 50)) {
   134→      const v = r[c];
   135→      if (v === null || v === undefined || v === '') continue;
   136→      if (typeof v === 'number') { seen++; continue; }
   137→      if (typeof v === 'string' && /^-?\d+(\.\d+)?([eE][+-]?\d+)?$/.test(v.trim())) { seen++; continue; }
   138→      return false;
   139→    }
   140→    return seen > 0;
   141→  });
   142→  if (numericCols.length === 0) return rows;
   143→  return rows.map((r) => {
   144→    const next: Record<string, any> = { ...r };
   145→    for (const c of numericCols) {
   146→      const v = next[c];
   147→      if (typeof v === 'string' && v.trim() !== '') {
   148→        const n = Number(v);
   149→        if (Number.isFinite(n)) next[c] = n;
   150→      }
   151→    }
   152→    return next;
   153→  });
   154→}
   155→
   156→/** 列统计摘要：数值列给 sum/avg/min/max，维度列给 distinct，辅助阶段二不编造数值 */
   157→export function buildColumnStats(rows: Record<string, any>[]): Record<string, any> {
   158→  if (rows.length === 0) return {};
   159→  const stats: Record<string, any> = {};
   160→  for (const c of Object.keys(rows[0])) {
   161→    const nums = rows
   162→      .map((r) => r[c])
   163→      .filter((v): v is number => typeof v === 'number' && Number.isFinite(v));
   164→    if (nums.length >= Math.max(1, Math.floor(rows.length * 0.5))) {
   165→      const sum = nums.reduce((a, b) => a + b, 0);
   166→      stats[c] = {
   167→        总计: Math.round(sum * 100) / 100,
   168→        均值: Math.round((sum / nums.length) * 100) / 100,
   169→        最小: Math.min(...nums),
   170→        最大: Math.max(...nums),
   171→      };
   172→    } else {
   173→      const distinct = new Set(rows.map((r) => String(r[c]))).size;
   174→      stats[c] = { 去重取值数: distinct };
   175→    }
   176→  }
   177→  return stats;
   178→}
   179→
   180→/** 矫正图表轴键：必须与真实 rows 的列名一致，否则前端渲染空白 */
   181→function rectifyChartKeys(
   182→  rows: Record<string, any>[],
   183→  xAxisKey: unknown,
   184→  yAxisKeys: unknown
   185→): { xAxisKey: string; yAxisKeys: string[] } {
   186→  const cols = rows.length > 0 ? Object.keys(rows[0]) : [];
   187→  const numericCols = cols.filter((c) => rows.some((r) => typeof r[c] === 'number'));
   188→  const dimCols = cols.filter((c) => !numericCols.includes(c));
   189→
   190→  let x = typeof xAxisKey === 'string' && cols.includes(xAxisKey) ? xAxisKey : '';
   191→  if (!x) x = dimCols[0] || cols[0] || '';
   192→
   193→  let ys = Array.isArray(yAxisKeys)
   194→    ? yAxisKeys.filter((k): k is string => typeof k === 'string' && cols.includes(k))
   195→    : [];
   196→  if (ys.length === 0) ys = numericCols.length > 0 ? numericCols.slice(0, 3) : cols.filter((c) => c !== x).slice(0, 1);
   197→  return { xAxisKey: x, yAxisKeys: ys };
   198→}
