   200→/**
   201→ * 组装结果列的中文表头映射：schema 列 description（管理员维护）为底，
   202→ * yAxisNames / LLM columnNames 覆盖（聚合别名的中文名只有 LLM 知道）。
   203→ * 只保留真实出现在结果行中的列，键全部限定为白名单内的列名。
   204→ */
   205→export function buildColumnNames(
   206→  rows: Record<string, any>[],
   207→  schema: any[],
   208→  ...overrides: Array<Record<string, string> | undefined>
   209→): Record<string, string> {
   210→  const cols = rows.length > 0 ? Object.keys(rows[0]) : [];
   211→  if (cols.length === 0) return {};
   212→  const out: Record<string, string> = {};
   213→  const tables = Array.isArray(schema) ? schema : [];
   214→  for (const col of cols) {
   215→    for (const t of tables) {
   216→      const c = (t?.columns || []).find((x: any) => x && x.name === col);
   217→      if (c && typeof c.description === 'string' && c.description.trim()) {
   218→        out[col] = c.description.trim();
   219→        break;
   220→      }
   221→    }
   222→  }
   223→  for (const map of overrides) {
   224→    if (!map || typeof map !== 'object') continue;
   225→    for (const col of cols) {
   226→      const v = map[col];
   227→      if (typeof v === 'string' && v.trim()) out[col] = v.trim().slice(0, 50);
   228→    }
   229→  }
   230→  return out;
   231→}
