   292→interface Stage1Plan {
   293→  sql: string;
   294→  title: string;
   295→  chartType: string;
   296→  xAxisKey: string;
   297→  yAxisKeys: string[];
   298→  yAxisNames?: Record<string, string>;
   299→  columnNames?: Record<string, string>;
   300→  thoughtProcess: string[];
   301→}
