   303→function parseStage1(text: string): Stage1Plan | null {
   304→  const parsed = safeParseJson(text);
   305→  if (!parsed) return null;
   306→  if (typeof parsed.sql !== 'string' || !parsed.sql.trim()) return null;
   307→  return {
   308→    sql: parsed.sql,
   309→    title: typeof parsed.title === 'string' && parsed.title.trim() ? parsed.title : '查询结果',
   310→    chartType: (VALID_STAGE1_CHARTS as readonly string[]).includes(parsed.chartType) ? parsed.chartType : 'bar',
   311→    xAxisKey: typeof parsed.xAxisKey === 'string' ? parsed.xAxisKey : '',
   312→    yAxisKeys: Array.isArray(parsed.yAxisKeys)
   313→      ? parsed.yAxisKeys.filter((k: any) => typeof k === 'string')
   314→      : [],
   315→    yAxisNames: parsed.yAxisNames && typeof parsed.yAxisNames === 'object' ? parsed.yAxisNames : undefined,
   316→    columnNames: parsed.columnNames && typeof parsed.columnNames === 'object' ? parsed.columnNames : undefined,
   317→    thoughtProcess: Array.isArray(parsed.thoughtProcess)
   318→      ? parsed.thoughtProcess.filter((s: any) => typeof s === 'string').slice(0, 6)
   319→      : [],
   320→  };
   321→}
