   323→/** 解析阶段一的澄清请求输出；非法/不完整（无有效选项）返回 null，由 SQL 契约兜底 */
   324→export function parseClarification(text: string): Clarification | null {
   325→  const parsed = safeParseJson(text);
   326→  if (!parsed || parsed.needClarification !== true) return null;
   327→  const c = parsed.clarification;
   328→  if (!c || typeof c !== 'object') return null;
   329→  if (typeof c.question !== 'string' || !c.question.trim()) return null;
   330→  if (!Array.isArray(c.options)) return null;
   331→  const options: ClarificationOption[] = c.options
   332→    .filter((o: any) => o && typeof o.label === 'string' && typeof o.query === 'string' && o.query.trim())
   333→    .slice(0, 4)
   334→    .map((o: any) => ({ label: String(o.label).trim().slice(0, 60), query: String(o.query).trim().slice(0, 500) }));
   335→  if (options.length === 0) return null;
   336→  return { question: c.question.trim().slice(0, 300), options };
   337→}
   338→
   339→/** 解析阶段一的拒答请求（问题与数据源无关/超出能力）；非法返回 null，由 SQL 契约兜底 */
   340→export function parseRefusal(text: string): { reason: string } | null {
   341→  const parsed = safeParseJson(text);
   342→  if (!parsed || parsed.refuse !== true) return null;
   343→  const reason = typeof parsed.reason === 'string' ? parsed.reason.trim().slice(0, 300) : '';
   344→  if (!reason) return null;
   345→  return { reason };
   346→}
   347→
   348→/**
   349→ * 拒答理由规范化：统一话术「抱歉，我是数据分析助手，仅协助处理数据分析相关工作，无法处理XXXX」。
   350→ * 小模型可能未遵模板（照抄旧模板句/XXXX 占位未填/理由过短），此处兜底改写并拼上数据源覆盖表清单。
   351→ */
   352→export function enrichRefusalReason(reason: string, schema: any[]): string {
   353→  // XXXX 占位未替换 → 降级为通用措辞
   354→  const cleaned = reason.replace(/x{2,}/gi, '该请求').trim();
   355→  const generic = cleaned.length < 30
   356→    || /与(当前)?数据源无关，或数据源中缺少支撑该问题的数据/.test(cleaned);
   357→  if (!generic) return cleaned;
   358→  const tables = (schema || [])
   359→    .map((t: any) => (t && typeof t.name === 'string' ? t.name.trim() : ''))
   360→    .filter(Boolean);
   361→  const scope = tables.length > 0
   362→    ? `当前数据源仅覆盖：${tables.slice(0, 8).join('、')}${tables.length > 8 ? ` 等 ${tables.length} 张表` : ''}。`
   363→    : '';
   364→  // 已是模板句式则保留；否则按统一话术改写（过短理由用「该请求」占位）
   365→  const what = cleaned.length < 15 ? '该请求' : cleaned.replace(/[。\.]+$/, '');
   366→  const core = /抱歉，我是数据分析助手/.test(cleaned)
   367→    ? cleaned.replace(/[。\.]+$/, '')
   368→    : `抱歉，我是数据分析助手，仅协助处理数据分析相关工作，无法处理${what}`;
   369→  return `${core}。${scope}`.slice(0, 400);
   370→}
   371→
   372→/** 解析阶段一的自省请求（Vanna intermediate_sql 借鉴）；非法返回 null，由 SQL 契约兜底 */
   373→export function parseIntrospection(text: string): { sql: string; note: string } | null {
   374→  const parsed = safeParseJson(text);
   375→  if (!parsed || parsed.needIntrospection !== true) return null;
   376→  const sql = typeof parsed.intermediateSql === 'string' ? parsed.intermediateSql.trim() : '';
   377→  if (!sql || !/^select\b/i.test(sql) || sql.length > 500) return null;
   378→  const note = typeof parsed.note === 'string' ? parsed.note.trim().slice(0, 100) : '';
   379→  return { sql, note };
   380→}
   381→
   382→/** 自省结果回喂格式：最多 30 行真实取值，JSON 紧凑呈现 */
   383→export function formatIntrospectionRows(rows: Record<string, any>[]): string {
   384→  return JSON.stringify(rows.slice(0, 30));
   385→}
   386→
   387→/**
   388→ * P1-B 自纠错候选数（借鉴 DB-GPT Self-consistency 思想）。
   389→ * 重试阶段可生成多条候选 SQL 择优，提升准确率；默认 1 等价原行为不增延迟，
   390→ * 通过 env SELF_CORRECT_CANDIDATES（2-3）按需开启。
   391→ */
   392→export function selfCorrectCandidates(): number {
   393→  const n = Number(process.env.SELF_CORRECT_CANDIDATES);
   394→  if (!Number.isFinite(n) || n <= 1) return 1;
   395→  return Math.min(3, Math.floor(n));
   396→}
   397→
   398→/** 多候选提示：首个候选用原 prompt，其余候选追加差异化引导以增加多样性 */
   399→export function candidatePrompt(base: string, index: number, total: number): string {
   400→  if (total <= 1 || index === 0) return base;
   401→  const hints = [
   402→    '请换一种聚合或分组思路重新生成。',
   403→    '请尽量简化 SQL，减少 JOIN 与子查询。',
   404→    '请优先使用最直接的表与列。',
   405→  ];
   406→  return `${base}\n\n（候选 ${index + 1}/${total}：${hints[(index - 1) % hints.length]}）`;
   407→}
   408→
   409→// ---------- 阶段二：真实 rows → 分析解读 ----------
   410→
   411→/**
   412→ * 阶段二异常降级：基于列统计生成规则化解读（不依赖 LLM）。
   413→ * 当 LLM 调用失败/超时/返回无效 JSON 时，用已有 stats + rows 构造有数据支撑的解读，
   414→ * 避免 "查询返回 N 行" 这种无信息量的兜底文案。
   415→ */
   416→export function buildFallbackAnalysis(
   417→  rows: Record<string, any>[],
   418→  stats: Record<string, any>,
   419→  columnNames: Record<string, string>,
   420→  chartConfig: Record<string, any>
   421→): { aiExplanation: string; keyInsights: string[]; kpiMetrics: any[] } {
   422→  const rowCount = rows.length;
   423→  const numericCols = Object.keys(stats).filter((c) => stats[c] && typeof stats[c].总计 === 'number');
   424→  const dimCols = Object.keys(stats).filter((c) => !numericCols.includes(c));
   425→
   426→  // 1. aiExplanation：按数据特征组织
   427→  const parts: string[] = [];
   428→  parts.push(`查询共返回 ${rowCount} 条记录`);
   429→
   430→  if (numericCols.length > 0) {
   431→    const top = numericCols.slice(0, 2);
   432→    const descs = top.map((c) => {
   433→      const s = stats[c];
   434→      const name = columnNames[c] || c;
   435→      return `${name}总计 ${s.总计.toLocaleString('zh-CN')}，均值 ${s.均值.toLocaleString('zh-CN')}，区间 ${s.最小} ~ ${s.最大}`;
   436→    });
   437→    parts.push(`；${descs.join('；')}`);
   438→  }
   439→
   440→  if (dimCols.length > 0) {
   441→    const d = dimCols[0];
   442→    const name = columnNames[d] || d;
   443→    parts.push(`；按${name}划分共 ${stats[d].去重取值数} 个维度`);
   444→  }
   445→
   446→  if (chartConfig.xAxisKey && chartConfig.yAxisKeys?.length > 0) {
   447→    const xName = columnNames[chartConfig.xAxisKey] || chartConfig.xAxisKey;
   448→    parts.push(`，图表以 ${xName} 为维度展示`);
   449→  }
   450→
   451→  parts.push('。');
   452→
   453→  // 2. keyInsights：从 stats 中提取 3 条
   454→  const insights: string[] = [];
   455→  if (numericCols.length > 0) {
   456→    const c = numericCols[0];
   457→    const s = stats[c];
   458→    const name = columnNames[c] || c;
   459→    insights.push(`${name}最高达 ${s.最大.toLocaleString('zh-CN')}，最低 ${s.最小.toLocaleString('zh-CN')}，波动幅度较大`);
   460→    if (numericCols.length > 1) {
   461→      const c2 = numericCols[1];
   462→      const s2 = stats[c2];
   463→      const name2 = columnNames[c2] || c2;
   464→      insights.push(`${name2}均值为 ${s2.均值.toLocaleString('zh-CN')}，总计 ${s2.总计.toLocaleString('zh-CN')}`);
   465→    }
   466→  }
   467→  if (dimCols.length > 0 && insights.length < 3) {
   468→    const d = dimCols[0];
   469→    const name = columnNames[d] || d;
   470→    insights.push(`按${name}细分共 ${stats[d].去重取值数} 个分组，可进一步下钻分析`);
   471→  }
   472→
   473→  // 3. kpiMetrics：取前 2 个数值列做 KPI 卡片
   474→  const kpis: any[] = [];
   475→  for (const c of numericCols.slice(0, 2)) {
   476→    const s = stats[c];
   477→    const name = columnNames[c] || c;
   478→    kpis.push({ label: `${name}（总计）`, value: s.总计.toLocaleString('zh-CN'), subtext: `均值 ${s.均值.toLocaleString('zh-CN')}` });
   479→    kpis.push({ label: `${name}（峰值）`, value: s.最大.toLocaleString('zh-CN'), subtext: `最小 ${s.最小.toLocaleString('zh-CN')}` });
   480→  }
   481→
   482→  return {
   483→    aiExplanation: parts.join(''),
   484→    keyInsights: insights.slice(0, 3),
   485→    kpiMetrics: kpis.slice(0, 4),
   486→  };
   487→}
   488→
   489→/** 阶段二角色设定：按用户问题路由专家 persona（财务/不良/客户/风险/默认金融分析师） */
   490→function buildStage2System(rolePrompt: string): string {
   491→  return `${rolePrompt}你将收到一次真实数据库查询的结果（SQL、行数、列统计与数据样本）。基于这些真实数据输出分析解读。
   492→
   493→【强制约束】
   494→- 仅输出 JSON 对象: {"aiExplanation","keyInsights","kpiMetrics","suggestedQuestions"}
   495→- 所有数值必须来自给定的真实数据与列统计，严禁编造任何数字
   496→- aiExplanation: 专业易懂的中文分析结论（120 字以内），须概括数据反映的核心事实
   497→- keyInsights: 3 条洞察数组，每条须引用真实维度值与指标数值
   498→- kpiMetrics: 2-4 个 KPI 卡片 [{"label","value","change","trend","subtext"}]；value 必须由真实数据计算得出（总计/均值/最大等，可引用列统计，可带单位如"万"）；change 仅当数据支持对比时给出（如时间序列首末期变化百分比），否则省略该字段；trend 从 up/down/neutral 选择
   499→- suggestedQuestions: 3 个后续追问，围绕当前 Schema 尚未充分利用的维度或指标
   500→- 若数据样本不足以支撑某结论，明确说明"基于当前返回数据"
   501→
   502→请只输出纯 JSON，不要包含 markdown 代码块标记或其他说明文字。`;
   503→}
   504→
   505→// ---------- 主编排 ----------
   506→
   507→export async function runLiveQuery(input: LiveQueryInput): Promise<LiveQueryOutcome> {
   508→  const { query, history, schema, guidance, dataSourceId, dsType, sensitiveRemoved } = input;
   509→  const trace = (step: TraceStep) => {
   510→    try {
   511→      input.onTrace?.(step);
   512→    } catch {
   513→      // 留痕失败不阻断主链路
   514→    }
   515→  };
   516→  const t0 = Date.now();
   517→  input.onStage?.('understanding');
   518→  // M2 计划模式：已批准计划先留痕，阶段一按其步骤引导生成（并跳过歧义澄清）
   519→  if (input.approvedPlan) {
   520→    trace({
   521→      stepType: 'plan',
   522→      title: '按已批准计划执行',
   523→      inputSummary: input.approvedPlan.understanding,
   524→      outputSummary: `${input.approvedPlan.steps.length} 个步骤：${input.approvedPlan.steps.map((s) => s.title).join(' → ')}`,
   525→      durationMs: Date.now() - t0,
   526→    });
   527→  }
   528→  // Schema Linking（借鉴 Chat2DB AI 数据集）：大 schema 时只把相关表注入 prompt（P2-9 关键词粗排 + embedding 精排）；
   529→  // 安全白名单（executeSafeSql）仍用全量 schema，召回遗漏不会误杀合法 SQL
   530→  const promptSchema = await selectRelevantTablesAsync(schema, query);
   531→  trace({
   532→    stepType: 'linking',
   533→    title: 'Schema 圈表：选定相关表',
   534→    inputSummary: query,
   535→    outputSummary: `命中 ${promptSchema.length}/${Array.isArray(schema) ? schema.length : 0} 张表：${promptSchema.map((t: any) => String(t?.name || '')).join(', ')}`,
   536→    durationMs: Date.now() - t0,
   537→  });
   538→  // 上下文构建并行化：few-shot / 知识库 RAG / 外部知识库 / 语义指标 / 点踩反例 / 个人对话沉淀六者互不依赖，并发执行（各自失败不阻断）
   539→  const [fewShotPairs, knowledgeRaw, externalKb, metricHits, negativePairs, convPairs] = await Promise.all([
   540→    // P0 Few-shot（DAIL-SQL 双维度）：用圈定表名引导样例贴近当前可查表
   541→    loadFewShotExamples(
   542→      dataSourceId,
   543→      query,
   544→      promptSchema.map((t: any) => String(t?.name || ''))
   545→    ).catch(() => [] as FewShotExample[]),
   546→    // P1-A 知识库 RAG：检索业务知识片段注入 prompt，按 token 预算截断
   547→    retrieveKnowledgeSnippets(dataSourceId, query).catch(() => ''),
   548→    // 外部知识库接入：管理员配置的企业级外部 RAG 检索，与本地知识一并作为自主学习来源（单源失败降级空）
   549→    searchExternalKnowledge(dataSourceId, query).catch(() => null),
   550→    // P1-1 语义指标层：问题命中指标名/同义词时模板化注入权威口径
   551→    loadActiveMetrics(dataSourceId)
   552→      .then((ms) => matchMetrics(query, ms))
   553→      .catch(() => []),
   554→    // 自主学习·反例：同数据源点踩问答对作为反面教材注入阶段一 prompt
   555→    loadNegativeExamples(dataSourceId, query).catch(() => [] as NegativeExample[]),
   556→    // 自主学习·个人沉淀：本人同数据源历史成功问答对作为个人 few-shot
   557→    loadConversationFewShot(
   558→      input.userId,
   559→      dataSourceId,
   560→      query,
   561→      promptSchema.map((t: any) => String(t?.name || ''))
   562→    ).catch(() => []),
   563→  ]);
   564→  // Vanna 借鉴：few-shot 以 user/assistant 消息对注入对话历史（比平铺文本更贴合 LLM 多轮格式）；
   565→  // 团队样例库在前，个人对话沉淀在后，均为「先问题后 SQL」格式
   566→  const fewShotHistory: ChatMessage[] = [
   567→    ...fewShotPairs.map((ex) => ({ question: ex.question, sql: ex.sql })),
   568→    ...convPairs,
   569→  ].flatMap((ex) => [
   570→    { role: 'user' as const, content: ex.question },
   571→    { role: 'assistant' as const, content: ex.sql },
   572→  ]);
   573→  const knowledge = budgetText(knowledgeRaw, KNOWLEDGE_TOKEN_BUDGET);
   574→  // 外部知识库片段独立预算控制，追加在本地知识之后（互不挤占注入槽位）
   575→  const externalSnippet = externalKb?.snippet || '';
   576→  trace({
   577→    stepType: 'knowledge',
   578→    title: '知识库检索与 Few-shot 样例',
   579→    inputSummary: query,
   580→    outputSummary: `知识片段 ${knowledge ? knowledge.length : 0} 字${externalSnippet ? `；外部知识库 ${externalSnippet.length} 字（成功 ${externalKb?.okSources ?? 0} 源${externalKb?.failSources ? `，失败 ${externalKb.failSources} 源` : ''}）` : ''}；few-shot 样例 ${fewShotPairs.length} 组（个人沉淀 ${convPairs.length} 组）；点踩反例 ${negativePairs.length} 组`,
   581→    durationMs: Date.now() - t0,
   582→  });
   583→  const metricPrompt = buildMetricPrompt(metricHits);
   584→  if (metricHits.length > 0) {
   585→    trace({
   586→      stepType: 'metrics',
   587→      title: '语义指标层命中',
   588→      inputSummary: query,
   589→      outputSummary: `命中 ${metricHits.length} 个指标定义：${metricHits.map((m) => m.name).join('、')}`,
   590→      durationMs: Date.now() - t0,
   591→    });
   592→  }
   593→  // M3 中间表清洗链：复杂度评估自动触发（multi-step）或「深度分析」开关强制；
   594→  // 清洗结果落库应用库中间表，阶段一可引用（仅引用 ait_* 时改在应用库执行）
   595→  let chainTables: IntermediateTableInfo[] = [];
   596→  const assessAt = Date.now();
   597→  // 深度分析开关强制时需 LLM 产出清洗计划（force）；否则启发式预门控无信号直接判 simple
   598→  const assessment = await assessComplexity(query, promptSchema, { force: Boolean(input.deepAnalysis) });
   599→  trace({
   600→    stepType: 'plan',
   601→    title: '复杂度评估',
   602→    inputSummary: query,
   603→    outputSummary: assessment.complexity === 'multi-step' ? `多步复杂分析，清洗计划 ${assessment.steps.length} 步` : '简单问题，直接生成 SQL',
   604→    durationMs: Date.now() - assessAt,
   605→  });
   606→  if (input.deepAnalysis || assessment.complexity === 'multi-step') {
   607→    const chain = await runAnalysisChain({
   608→      question: query,
   609→      dataSourceId,
   610→      schema,
   611→      sensitiveRemoved,
   612→      assessment,
   613→      userId: input.userId,
   614→      traceId: input.traceId,
   615→      onTrace: input.onTrace,
   616→    }).catch(() => null);
   617→    if (chain) chainTables = chain.tables;
   618→  }
   619→  const stage1System = buildStage1System(promptSchema, guidance, knowledge + externalSnippet, fewShotPairs.length + convPairs.length, dsType, Boolean(input.allowIntrospection), input.approvedPlan, chainTables, metricPrompt, negativePairs);
   620→  // 多轮历史按 token 预算截断（保留最近轮次），与 few-shot 消息对拼接后注入阶段一
   621→  const budgetedHistory = budgetHistory(history);
   622→  // 专家角色路由：财务/客户/风险/不良关键词命中对应专家，否则默认金融数据分析师
   623→  const persona = resolveExpertPersona(query);
   624→
   625→  let retries = 0;
   626→  let plan: Stage1Plan | null = null;
   627→  let exec: Awaited<ReturnType<typeof executeSafeSql>> | null = null;
   628→  let lastError = '';
   629→  // 数据自省仅首次尝试允许一轮（防止递归内省拖慢响应）
   630→  let introspected = false;
   631→
   632→  // P1-B 自纠错：重试阶段可生成多候选 SQL 择优（默认 1 个，等价原行为）
   633→  const candidateCount = selfCorrectCandidates();
   634→
   635→  // 阶段一 + 执行，失败时把原因回喂 LLM 重试一次
   636→  for (let attempt = 0; attempt < 2; attempt++) {
   637→    const unitPrefix = buildAmountUnitPrompt(normalizeAmountUnit(input.amountUnit));
   638→    const basePrompt =
   639→      attempt === 0
   640→        ? `${unitPrefix}${query}`
   641→        : `${unitPrefix}${query}\n\n（上次生成的 SQL 未通过校验或执行失败：${lastError}。请修正后按同一 JSON 契约重新输出。）`;
   642→    // 首次 1 个候选；重试时按 candidateCount 生成多候选（Self-consistency 择优）
   643→    const n = attempt === 0 ? 1 : candidateCount;
   644→    const plans: Stage1Plan[] = [];
   645→
   646→    // P2-6 重试阶段多候选并行生成（互不依赖，Promise.allSettled 后统一择优）；
   647→    // 首个候选保持串行：需先走歧义澄清 / 数据自省判定
   648→    const texts: string[] = [];
   649→    if (attempt === 0) {
   650→      try {
   651→        texts.push(await callLLMJson(stage1System, candidatePrompt(basePrompt, 0, 1), [...fewShotHistory, ...budgetedHistory], { route: sqlStageRoute() }));
   652→      } catch (err: any) {
   653→        return { ok: false, error: `LLM 调用失败：${String(err?.message || err).slice(0, 200)}` };
   654→      }
   655→    } else {
   656→      const settled = await Promise.allSettled(
   657→        Array.from({ length: n }, (_, i) =>
   658→          callLLMJson(stage1System, candidatePrompt(basePrompt, i, n), [...fewShotHistory, ...budgetedHistory], { route: sqlStageRoute() })
   659→        )
   660→      );
   661→      for (const r of settled) {
   662→        if (r.status === 'fulfilled') texts.push(r.value);
   663→      }
   664→    }
   665→
   666→    let candidateIndex = 0;
   667→    for (const text of texts) {
   668→      // 歧义澄清：仅首次尝试的第一个候选在接受（重试阶段视为用户已确认，按 SQL 契约执行）；
   669→      // 计划模式下用户已批准计划，视为已确认理解，不再触发澄清
   670→      if (attempt === 0 && candidateIndex === 0 && !input.approvedPlan) {
   671→        const clarification = parseClarification(text);
   672→        if (clarification) return { ok: 'clarify', clarification };
   673→        // 拒答：问题与数据源无关/超出能力，如实反馈，不走演示数据托底（仅首候选首次尝试接受）
   674→        const refusal = parseRefusal(text);
   675→        if (refusal) {
   676→          trace({ stepType: 'sql_gen', title: 'SQL 生成（拒答）', inputSummary: query, outputSummary: refusal.reason, status: 'fail', durationMs: Date.now() - t0 });
   677→          return { ok: 'refuse', reason: refusal.reason };
   678→        }
   679→      }
   680→      // 数据自省（Vanna intermediate_sql）：真实执行轻量自省 SQL，把实际取值回喂后再生成最终 SQL
   681→      if (attempt === 0 && candidateIndex === 0 && input.allowIntrospection && !introspected) {
   682→        const intro = parseIntrospection(text);
   683→        if (intro) {
   684→          introspected = true;
   685→          input.onStage?.('introspecting', { note: intro.note });
   686→          const introAt = Date.now();
   687→          const introExec = await executeSafeSql(dataSourceId, intro.sql, schema, sensitiveRemoved, 500, input.rowFilters || {});
   688→          if (introExec.ok === true) {
   689→            trace({
   690→              stepType: 'introspection',
   691→              title: '数据自省：确认实际取值',
   692→              inputSummary: intro.note || '确认过滤条件的真实取值',
   693→              sqlText: intro.sql,
   694→              rowCount: introExec.result.rows.length,
   695→              durationMs: Date.now() - introAt,
   696→            });
   697→            try {
   698→              const finalText = await callLLMJson(
   699→                stage1System,
   700→                `${query}\n\n【数据自省结果】${formatIntrospectionRows(introExec.result.rows)}\n请基于上述真实取值确定过滤条件，直接输出最终 SQL 的 JSON 契约（禁止再输出 needClarification 或 needIntrospection）`,
   701→                [...fewShotHistory, ...budgetedHistory],
   702→                { route: sqlStageRoute() }
   703→              );
   704→              const fp = parseStage1(finalText);
   705→              if (fp) plans.push(fp);
   706→            } catch {
   707→              // 自省后的最终生成失败，走常规重试链路
   708→            }
   709→            candidateIndex++;
   710→            continue;
   711→          }
   712→        }
   713→      }
   714→      const p = parseStage1(text);
   715→      if (p) plans.push(p);
   716→      candidateIndex++;
   717→    }
   718→    if (plans.length === 0) {
   719→      lastError = 'LLM 输出未通过 SQL 契约校验';
   720→      retries++;
   721→      trace({ stepType: 'sql_gen', title: `SQL 生成（第 ${attempt + 1} 次）`, inputSummary: query, outputSummary: lastError, status: 'fail', durationMs: Date.now() - t0 });
   722→      continue;
   723→    }
   724→    trace({
   725→      stepType: 'sql_gen',
   726→      title: `SQL 生成（第 ${attempt + 1} 次${plans.length > 1 ? `，${plans.length} 个候选择优` : ''}）`,
   727→      inputSummary: query,
   728→      outputSummary: plans.map((p) => p.title).join('；'),
   729→      sqlText: plans[0].sql,
   730→      durationMs: Date.now() - t0,
   731→    });
   732→    // P2-1 SQL 先行回显：候选确定即推送（执行前），长执行等待期用户可先看到生成的 SQL
   733→    input.onStage?.('sql_ready', { sql: plans[0].sql });
   734→    // 逐候选执行，取第一个成功（SELECT-only 只读，安全）；
   735→    // M3：仅引用已注册 ait_* 中间表的 SQL 改在应用库执行（不得与源表混用）
   736→    let succeeded = false;
   737→    const registeredAit = chainTables.length > 0 ? await getRegisteredAitNames() : new Set<string>();
   738→    for (const p of plans) {
   739→      const execAt = Date.now();
   740→      const aitRefs = extractAitRefs(p.sql);
   741→      if (aitRefs.length > 0) {
   742→        exec = await executeOnAppDb(p.sql, registeredAit);
   743→      } else {
   744→        exec = await executeSafeSql(dataSourceId, p.sql, schema, sensitiveRemoved, 500, input.rowFilters || {});
   745→      }
   746→      if (exec.ok === true) {
   747→        plan = p;
   748→        succeeded = true;
   749→        input.onStage?.('executed', { sql: exec.result.finalSql, rowCount: exec.result.rows.length });
   750→        trace({
   751→          stepType: 'execution',
   752→          title: aitRefs.length > 0 ? '安全执行 SQL（分析库中间表）' : '安全执行 SQL',
   753→          inputSummary: aitRefs.length > 0 ? `引用中间表：${aitRefs.join(', ')}` : 'SELECT-only 白名单校验通过',
   754→          sqlText: exec.result.finalSql,
   755→          rowCount: exec.result.rows.length,
   756→          durationMs: Date.now() - execAt,
   757→        });
