   781→    const n = plan.yAxisNames?.[k] || columnNames[k];
   782→    if (n) yAxisNames[k] = n;
   783→  }
   784→  const chartConfig = {
   785→    type: plan.chartType,
   786→    title: plan.title,
   787→    xAxisKey: keys.xAxisKey,
   788→    yAxisKeys: keys.yAxisKeys,
   789→    ...(Object.keys(yAxisNames).length > 0 ? { yAxisNames } : {}),
   790→    ...(columnNames[keys.xAxisKey] ? { xAxisName: columnNames[keys.xAxisKey] } : {}),
   791→  };
   792→
   793→  // 空结果集：跳过阶段二，直接给出真实结论
   794→  if (rows.length === 0) {
   795→    return {
   796→      ok: true,
   797→      executedSql: finalSql,
   798→      rowCount: 0,
   799→      retries,
   800→      result: {
