   858→    inputSummary: `真实结果 ${exec.result.rowCount} 行 + 列统计回喂`,
   859→    outputSummary: typeof analysis.aiExplanation === 'string' ? analysis.aiExplanation : '解读生成失败，使用兜底文案',
   860→    durationMs: Date.now() - analyzeAt,
