     1→/**
     2→ * 问数范围（DataScope）过滤。
     3→ * scope 结构：{ tables: string[], columns?: { [tableId]: string[] }, rowFilters?: { [tableId]: 谓词 } }
     4→ * - scope 为空或 tables 为空数组 = 不限制（全部表/全部字段）
     5→ * - tables 非空 = 仅这些表纳入问数；columns[tableId] 非空时进一步限制字段
     6→ * - P1-3 rowFilters[tableId]：行级权限谓词（WHERE 片段），执行层 AST 强制注入
     7→ */
     8→
     9→export interface DataScope {
    10→  tables: string[];
    11→  columns?: Record<string, string[]>;
    12→  /** P1-3 行级权限：tableId → 行过滤谓词（管理员登记，执行层强制注入） */
    13→  rowFilters?: Record<string, string>;
    14→}
    15→
    16→/** 校验行过滤谓词：管理员登记但仍防结构性注入（多语句/注释/子查询/INTO） */
    17→export function sanitizeRowFilterPredicate(pred: unknown): string | null {
    18→  if (typeof pred !== 'string') return null;
    19→  const p = pred.trim();
    20→  if (!p || p.length > 300) return null;
    21→  if (/;/.test(p)) return null;
    22→  if (/--|#|\/\*/.test(p)) return null;
    23→  if (/\bselect\b|\binto\b/i.test(p)) return null;
    24→  return p;
    25→}
    26→
    27→export function applyDataScope(tables: any[], scope: DataScope | null | undefined): any[] {
    28→  if (!Array.isArray(tables)) return [];
    29→  if (!scope || !Array.isArray(scope.tables) || scope.tables.length === 0) return tables;
    30→
    31→  const allowedTables = new Set(scope.tables);
    32→  const colMap = scope.columns && typeof scope.columns === 'object' ? scope.columns : {};
    33→
    34→  return tables
    35→    .filter((t) => allowedTables.has(t.id))
    36→    .map((t) => {
    37→      const allowedCols = Array.isArray(colMap[t.id]) && colMap[t.id].length > 0 ? new Set(colMap[t.id]) : null;
    38→      if (!allowedCols) return t;
    39→      return { ...t, columns: (t.columns || []).filter((c: any) => allowedCols.has(c.name)) };
    40→    });
    41→}
    42→
    43→/** 依据数据源现有 schema 清洗 scope：剔除已不存在的表与字段（同步漂移容错） */
    44→export function sanitizeDataScope(tables: any[], scope: any): DataScope | null {
    45→  if (!scope || !Array.isArray(scope.tables)) return null;
    46→
    47→  const tableIds = new Set(tables.map((t) => t.id));
    48→  const cleanTables = scope.tables.filter((id: any) => typeof id === 'string' && tableIds.has(id));
    49→
    50→  const cleanColumns: Record<string, string[]> = {};
    51→  const rawCols = scope.columns && typeof scope.columns === 'object' ? scope.columns : {};
    52→  for (const tid of cleanTables) {
    53→    const cols = rawCols[tid];
    54→    if (!Array.isArray(cols) || cols.length === 0) continue;
    55→    const table = tables.find((t) => t.id === tid);
    56→    const validNames = new Set((table?.columns || []).map((c: any) => c.name));
    57→    const kept = cols.filter((n: any) => typeof n === 'string' && validNames.has(n));
    58→    if (kept.length > 0) cleanColumns[tid] = kept;
    59→  }
    60→
    61→  // P1-3 行级权限谓词清洗：仅保留真实存在表 + 谓词结构合法（可独立于表/列限制生效）
    62→  const cleanRowFilters: Record<string, string> = {};
    63→  const rawFilters = scope.rowFilters && typeof scope.rowFilters === 'object' ? scope.rowFilters : {};
    64→  for (const [tid, pred] of Object.entries(rawFilters)) {
    65→    if (!tableIds.has(tid)) continue;
    66→    const p = sanitizeRowFilterPredicate(pred);
    67→    if (p) cleanRowFilters[tid] = p;
    68→  }
    69→
    70→  if (cleanTables.length === 0 && Object.keys(cleanColumns).length === 0 && Object.keys(cleanRowFilters).length === 0) {
    71→    return null;
    72→  }
    73→
    74→  return {
    75→    tables: cleanTables,
    76→    columns: cleanColumns,
    77→    ...(Object.keys(cleanRowFilters).length > 0 ? { rowFilters: cleanRowFilters } : {}),
    78→  };
    79→}
    80→
    81→/**
    82→ * P1-3 行级权限映射：tableId 键 → 实际表名键（执行层 AST 注入按 SQL 中的真实表名匹配）。
    83→ * 参数 tables 传 scope 过滤后的 schema，确保只对问数可见表生效。
    84→ */
    85→export function rowFiltersByTableName(tables: any[], scope: DataScope | null | undefined): Record<string, string> {
    86→  const out: Record<string, string> = {};
    87→  if (!scope || !scope.rowFilters || typeof scope.rowFilters !== 'object') return out;
    88→  for (const t of Array.isArray(tables) ? tables : []) {
    89→    const pred = sanitizeRowFilterPredicate(scope.rowFilters[t.id]);
    90→    if (pred && typeof t.name === 'string' && t.name) out[t.name] = pred;
    91→  }
    92→  return out;
    93→}
    94→

