    81→/**
    82→ * P1-3 行级权限映射：tableId 键 → 实际表名键（执行层 AST 注入按 SQL 中的真实表名匹配）。
    83→ * 参数 tables 传 scope 过滤后的 schema，确保只对问数可见表生效。
    84→ */
    85→export function rowFiltersByTableName(tables: any[], scope: DataScope | null | undefined): Record<string, string> {
    86→  const out: Record<string, string> = {};
    87→  if (!scope || !scope.rowFilters || typeof scope.rowFilters !== 'object') return out;
    88→  for (const t of Array.isArray(tables) ? tables : []) {
    89→    const pred = sanitizeRowFilterPredicate(scope.rowFilters[t.id]);
    90→    if (pred && typeof t.name === 'string' && t.name) out[t.name] = pred;
    91→  }
    92→  return out;
    93→}
