     1→/**
     2→ * P1-6 问数结果语义缓存：同一数据源下归一化后相同的问题短期内直接复用结果，
     3→ * 避免重复触发昂贵的 LLM 链路。仅缓存 live 链路成功结果。
     4→ * P0-2：默认内存 Map（进程重启自然失效）；配置 REDIS_URL 后外置 Redis，多实例共享。
     5→ */
     6→import { getStateStore, isRedisEnabled } from './stateStore';
     7→
     8→const CACHE_TTL_MS = 10 * 60 * 1000;
     9→const MAX_ENTRIES = 200;
    10→/** Redis 缓存值体积上限（超过不缓存，避免大结果集撑爆内存库） */
    11→const REDIS_MAX_PAYLOAD_BYTES = 200 * 1024;
    12→
    13→/** 问题归一化：小写 + 去除空白与常见标点，保证「各客户类型的数量？」与「各客户类型的数量」命中同一缓存 */
    14→export function normalizeQuestion(q: string): string {
    15→  return String(q || '')
    16→    .toLowerCase()
    17→    .replace(/[\s，。！？,.!?;；：:"'"“”‘’、（）()]+/g, '')
    18→    .slice(0, 200);
    19→}
    20→
    21→/** variant 用于区分不同模型/引擎下的结果（用户自选模型时传 "engine:model"），避免跨模型串用缓存 */
    22→export function cacheKey(dataSourceId: string, question: string, variant = ''): string {
    23→  const base = `${dataSourceId}::${normalizeQuestion(question)}`;
    24→  return variant ? `${base}::${variant}` : base;
    25→}
    26→
    27→interface CacheEntry {
    28→  payload: any;
    29→  at: number;
    30→}
    31→
    32→const cache = new Map<string, CacheEntry>();
    33→
    34→export async function getCachedQuery(key: string): Promise<any | null> {
    35→  if (isRedisEnabled()) {
    36→    try {
    37→      const raw = await getStateStore().get(`qc:${key}`);
    38→      return raw ? JSON.parse(raw) : null;
    39→    } catch {
    40→      return null; // Redis 异常按未命中处理（缓存 fail-open）
    41→    }
    42→  }
    43→  const entry = cache.get(key);
    44→  if (!entry) return null;
    45→  if (Date.now() - entry.at > CACHE_TTL_MS) {
    46→    cache.delete(key);
    47→    return null;
    48→  }
    49→  return entry.payload;
    50→}
    51→
    52→export async function setCachedQuery(key: string, payload: any): Promise<void> {
    53→  if (isRedisEnabled()) {
    54→    try {
    55→      const raw = JSON.stringify(payload);
    56→      if (raw.length <= REDIS_MAX_PAYLOAD_BYTES) {
    57→        await getStateStore().setEx(`qc:${key}`, raw, Math.ceil(CACHE_TTL_MS / 1000));
    58→      }
    59→    } catch {
    60→      // 写缓存失败静默忽略（fail-open）
    61→    }
    62→    return;
    63→  }
    64→  // 简易容量控制：超出上限时淘汰最早写入的条目
    65→  if (cache.size >= MAX_ENTRIES) {
    66→    const oldest = cache.keys().next().value;
    67→    if (oldest !== undefined) cache.delete(oldest);
    68→  }
    69→  cache.set(key, { payload, at: Date.now() });
    70→}
    71→
    72→/** 数据源结构变更后清理其缓存（Redis 模式按前缀 SCAN 删除） */
    73→export async function invalidateQueryCache(dataSourceId?: string): Promise<void> {
    74→  if (isRedisEnabled()) {
    75→    try {
    76→      await getStateStore().deleteByPrefix(dataSourceId ? `qc:${dataSourceId}::` : 'qc:');
    77→    } catch {
    78→      // 失效操作失败不阻断主流程
    79→    }
    80→    return;
    81→  }
    82→  if (!dataSourceId) {
    83→    cache.clear();
    84→    return;
    85→  }
    86→  for (const k of cache.keys()) {
    87→    if (k.startsWith(`${dataSourceId}::`)) cache.delete(k);
    88→  }
    89→}
    90→

