     1→/**
     2→ * 认证与授权模块：JWT 签发/校验 + Express 鉴权中间件。
     3→ * 中间件在验证 token 后回查 users 表，确保禁用/角色变更立即生效。
     4→ */
     5→import type express from 'express';
     6→import { randomBytes } from 'crypto';
     7→import jwt from 'jsonwebtoken';
     8→import { getPool } from './db';
     9→import { setLlmUserContext } from './llmClient';
    10→
    11→export type UserRole = 'ADMIN' | 'ANALYST' | 'VIEWER';
    12→
    13→export interface AuthUser {
    14→  id: number;
    15→  username: string;
    16→  displayName: string;
    17→  role: UserRole;
    18→  /** 首登/被重置密码后置位：改密前禁止访问一切业务接口（/api/auth 放行） */
    19→  mustChangePassword?: boolean;
    20→}
    21→
    22→declare global {
    23→  // eslint-disable-next-line @typescript-eslint/no-namespace
    24→  namespace Express {
    25→    interface Request {
    26→      user?: AuthUser;
    27→    }
    28→  }
    29→}
    30→
    31→// ESM import 提升会使模块级 process.env 读取早于 dotenv.config()， 须惰性读取
    32→// dev 兜底密钥：进程级随机生成（重启后登录态失效），杜绝固定串被复制到测试/预发环境伪造 token。
    33→// 注：secretsCrypto 的数据源凭据密钥不可随机化（落库密文需跨重启解密），生产由 server.ts fail-fast 拦截。
    34→let devJwtSecret: string | null = null;
    35→const jwtSecret = (): string => {
    36→  if (process.env.JWT_SECRET) return process.env.JWT_SECRET;
    37→  if (!devJwtSecret) {
    38→    devJwtSecret = randomBytes(32).toString('hex');
    39→    console.warn('[Security] ⚠️ JWT_SECRET 未配置，已生成进程级临时密钥（重启后所有登录态失效）；生产环境必须配置固定强密钥');
    40→  }
    41→  return devJwtSecret;
    42→};
    43→const jwtExpiresIn = () => process.env.JWT_EXPIRES_IN || '12h';
    44→
    45→export function signToken(user: AuthUser): string {
    46→  return jwt.sign({ sub: user.id, username: user.username, role: user.role }, jwtSecret(), {
    47→    expiresIn: jwtExpiresIn(),
    48→  } as jwt.SignOptions);
    49→}
    50→
    51→/** 校验 Bearer token 并回查用户状态，附加 req.user */
    52→export async function authMiddleware(
    53→  req: express.Request,
    54→  res: express.Response,
    55→  next: express.NextFunction
    56→) {
    57→  const header = req.headers.authorization || '';
    58→  const token = header.startsWith('Bearer ') ? header.slice(7) : null;
    59→  if (!token) {
    60→    return res.status(401).json({ error: '未登录或登录已过期' });
    61→  }
    62→
    63→  let payload: jwt.JwtPayload;
    64→  try {
    65→    payload = jwt.verify(token, jwtSecret()) as jwt.JwtPayload;
    66→  } catch {
    67→    return res.status(401).json({ error: '登录状态无效，请重新登录' });
    68→  }
    69→
    70→  try {
    71→    const [rows] = await getPool().query(
    72→      'SELECT id, username, display_name, role, status, must_change_password FROM users WHERE id = ? LIMIT 1',
    73→      [payload.sub]
    74→    );
    75→    const user = (rows as any[])[0];
    76→    if (!user || user.status !== 'ACTIVE') {
    77→      return res.status(401).json({ error: '账号不存在或已被禁用' });
    78→    }
    79→    req.user = {
    80→      id: user.id,
    81→      username: user.username,
    82→      displayName: user.display_name,
    83→      role: user.role,
    84→      mustChangePassword: !!user.must_change_password,
    85→    };
    86→    // LLM 用量按用户统计：鉴权后注入请求级用户上下文（本次请求异步链内的 LLM 埋点均携带）
    87→    setLlmUserContext(user.id, user.username);
    88→    // P0-1 服务端强制改密：首登/被重置密码的用户，改密前只放行 /api/auth/*（登录/改密/当前用户）
    89→    if (user.must_change_password && !req.originalUrl.startsWith('/api/auth/')) {
    90→      return res.status(403).json({ code: 'PASSWORD_CHANGE_REQUIRED', error: '首次登录或密码已被重置，请先修改密码' });
    91→    }
    92→    next();
    93→  } catch (err) {
    94→    console.error('[Auth] user lookup failed:', err);
    95→    return res.status(500).json({ error: '认证服务异常' });
    96→  }
    97→}
    98→
    99→/** 角色守卫：requireRole('ADMIN') / requireRole('ADMIN','ANALYST') */
   100→export function requireRole(...roles: UserRole[]) {
   101→  return (req: express.Request, res: express.Response, next: express.NextFunction) => {
   102→    if (!req.user) {
   103→      return res.status(401).json({ error: '未登录' });
   104→    }
   105→    if (!roles.includes(req.user.role)) {
   106→      return res.status(403).json({ error: '没有权限执行此操作' });
   107→    }
   108→    next();
   109→  };
   110→}
   111→

