     1→/**
     2→ * M1 推导过程留痕：问数全链路每一步记录到 query_trace 表，
     3→ * 支持事后回放（每个环节的输入摘要/输出摘要/SQL/行数/耗时均可查看）。
     4→ * 记录为旁路写入：失败不影响问数主链路（fire-and-forget）。
     5→ */
     6→import type { RowDataPacket } from 'mysql2';
     7→import { getPool } from './db';
     8→
     9→export type TraceStepType =
    10→  | 'understanding'
    11→  | 'linking'
    12→  | 'knowledge'
    13→  | 'metrics'
    14→  | 'introspection'
    15→  | 'plan'
    16→  | 'intermediate'
    17→  | 'sql_gen'
    18→  | 'execution'
    19→  | 'analysis'
    20→  | 'report';
    21→
    22→export interface TraceStep {
    23→  stepType: TraceStepType;
    24→  title: string;
    25→  /** 输入摘要（问题/上下文要点），截断后存储 */
    26→  inputSummary?: string;
    27→  /** 输出摘要（结论/命中内容要点），截断后存储 */
    28→  outputSummary?: string;
    29→  sqlText?: string;
    30→  rowCount?: number;
    31→  durationMs?: number;
    32→  status?: 'ok' | 'fail';
    33→}
    34→
    35→export interface TraceMeta {
    36→  userId: number;
    37→  username: string;
    38→  dataSourceId: string;
    39→  question: string;
    40→}
    41→
    42→export function newTraceId(): string {
    43→  return `tr_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 10)}`;
    44→}
    45→
    46→function clip(text: string | undefined, max: number): string {
    47→  if (typeof text !== 'string') return '';
    48→  const t = text.trim();
    49→  return t.length > max ? `${t.slice(0, max)}…` : t;
    50→}
    51→
    52→/** 旁路写入一步推导记录；调用方不必 await，失败仅打日志不阻断主链路 */
    53→export function recordTraceStep(traceId: string, meta: TraceMeta, step: TraceStep): Promise<void> {
    54→  let pool;
    55→  try {
    56→    pool = getPool();
    57→  } catch {
    58→    return Promise.resolve(); // DB 未初始化（如纯单测环境）静默跳过
    59→  }
    60→  return pool
    61→    .query(
    62→      `INSERT INTO query_trace
    63→        (trace_id, user_id, username, data_source_id, question, step_type, title, input_summary, output_summary, sql_text, row_count, duration_ms, status)
    64→       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    65→      [
    66→        traceId,
    67→        meta.userId,
    68→        meta.username,
    69→        meta.dataSourceId,
    70→        clip(meta.question, 500),
    71→        step.stepType,
    72→        clip(step.title, 100),
    73→        clip(step.inputSummary, 1000),
    74→        clip(step.outputSummary, 2000),
    75→        clip(step.sqlText, 2000),
    76→        typeof step.rowCount === 'number' ? step.rowCount : -1,
    77→        typeof step.durationMs === 'number' ? Math.round(step.durationMs) : 0,
    78→        step.status === 'fail' ? 'fail' : 'ok',
    79→      ]
    80→    )
    81→    .then(() => undefined)
    82→    .catch((err: any) => {
    83→      console.warn('[Trace] record failed:', String(err?.message || err).slice(0, 120));
    84→    });
    85→}
    86→
    87→export interface TraceStepRow extends TraceStep {
    88→  stepIndex: number;
    89→  createdAt: string;
    90→}
    91→
    92→/** 读取一次问数的完整推导链（按步骤顺序） */
    93→export async function getTraceSteps(traceId: string): Promise<{ steps: TraceStepRow[]; ownerUserId: number | null }> {
    94→  const pool = getPool();
    95→  const [rows] = await pool.query<RowDataPacket[]>(
    96→    `SELECT step_type, title, input_summary, output_summary, sql_text, row_count, duration_ms, status, user_id, created_at
    97→     FROM query_trace WHERE trace_id = ? ORDER BY id ASC LIMIT 50`,
    98→    [traceId]
    99→  );
   100→  if (rows.length === 0) return { steps: [], ownerUserId: null };
   101→  const steps: TraceStepRow[] = rows.map((r, i) => ({
   102→    stepIndex: i + 1,
   103→    stepType: String(r.step_type) as TraceStepType,
   104→    title: String(r.title || ''),
   105→    inputSummary: String(r.input_summary || ''),
   106→    outputSummary: String(r.output_summary || ''),
   107→    sqlText: String(r.sql_text || ''),
   108→    rowCount: Number(r.row_count),
   109→    durationMs: Number(r.duration_ms),
   110→    status: r.status === 'fail' ? 'fail' : 'ok',
   111→    createdAt: String(r.created_at || ''),
   112→  }));
   113→  return { steps, ownerUserId: Number(rows[0].user_id) };
   114→}
