     1→/**
     2→ * Prompt 资源预算控制（借鉴 Vanna max_tokens 截断机制）。
     3→ * 本地大模型上下文有限，知识库/few-shot/历史对话无限注入会拖慢推理并稀释注意力，
     4→ * 统一按近似 token 预算截断：中文约 1 字 1 token，取保守估计（length / 1.5）。
     5→ */
     6→
     7→/** 近似 token 估算（保守偏高，宁少勿超） */
     8→export function approxTokens(text: string): number {
     9→  return Math.ceil(String(text || '').length / 1.5);
    10→}
    11→
    12→/** 将文本裁剪到 token 预算内（按字符边界截断） */
    13→export function budgetText(text: string, maxTokens: number): string {
    14→  const t = String(text || '');
    15→  if (approxTokens(t) <= maxTokens) return t;
    16→  return t.slice(0, Math.max(0, Math.floor(maxTokens * 1.5)));
    17→}
    18→
    19→/** 知识库片段注入预算 */
    20→export const KNOWLEDGE_TOKEN_BUDGET = 1800;
    21→/** 外部知识库片段注入预算（与本地知识库分开控制，避免外部源挤占本地口径注入） */
    22→export const EXTERNAL_KB_TOKEN_BUDGET = 1200;
    23→/** few-shot 样例注入预算 */
    24→export const FEWSHOT_TOKEN_BUDGET = 1800;
    25→/** 多轮历史对话预算（保留最近若干轮，从新到旧贪心） */
    26→export const HISTORY_TOKEN_BUDGET = 1500;
    27→
    28→/** 历史消息按预算截断：从最新往前贪心保留，保持原始顺序返回 */
    29→export function budgetHistory<T extends { content: string }>(messages: T[], maxTokens = HISTORY_TOKEN_BUDGET): T[] {
    30→  const kept: T[] = [];
    31→  let used = 0;
    32→  for (let i = messages.length - 1; i >= 0; i--) {
    33→    const cost = approxTokens(messages[i].content);
    34→    if (used + cost > maxTokens && kept.length > 0) break;
    35→    used += cost;
    36→    kept.unshift(messages[i]);
    37→  }
    38→  return kept;
    39→}
    40→

