    22→const qwenUrl = () => process.env.QWEN_URL || 'https://dashscope.aliyuncs.com/compatible-mode/v1';
    23→const qwenModel = () => overrideModel('qwen') || process.env.QWEN_MODEL || 'qwen3.8-max';
    24→const qwenTimeoutMs = () => Number(process.env.QWEN_TIMEOUT_MS) || 180_000;
    25→const GEMINI_MODEL = 'gemini-3.6-flash';
    26→const geminiModel = () => overrideModel('gemini') || GEMINI_MODEL;
    27→
    28→type EngineKind = 'ollama' | 'gemini' | 'qwen';
    29→
    30→/** 阶段级模型路由（P1-2）：调用方可为单次调用指定引擎/模型（如 SQL 生成用快速小模型） */
    31→export interface LlmStageRoute {
    32→  engine: EngineKind;
    33→  model: string;
    34→}
    35→
    36→/**
    37→ * 阶段级模型路由通用解析：环境变量指定引擎+模型均合法时启用（结构化任务用快速小模型更快更稳）。
    38→ */
    39→function stageRouteFromEnv(engineVar: string, modelVar: string): LlmStageRoute | undefined {
    40→  const engine = String(process.env[engineVar] || '').toLowerCase();
    41→  const model = String(process.env[modelVar] || '').trim();
    42→  if (engine !== 'ollama' && engine !== 'gemini' && engine !== 'qwen') return undefined;
    43→  if (!model || model.length > 100 || !/^[\w.:\-]+$/.test(model)) return undefined;
    44→  return { engine: engine as EngineKind, model };
    45→}
    46→
    47→/**
    48→ * SQL 生成阶段的快速模型路由（P1-2）：LLM_SQL_ENGINE + LLM_SQL_MODEL 均配置且合法时启用。
    49→ * 作用于阶段一与复杂度评估（结构化输出任务小模型更快更稳）；阶段二解读默认仍用主模型。
    50→ */
    51→export function sqlStageRoute(): LlmStageRoute | undefined {
    52→  return stageRouteFromEnv('LLM_SQL_ENGINE', 'LLM_SQL_MODEL');
    53→}
    54→
    55→/**
    56→ * 阶段二数据解读的快速模型路由：LLM_ANALYSIS_ENGINE + LLM_ANALYSIS_MODEL 均配置时启用。
    57→ * 解读是问数链路最大耗时项，配置快速模型可大幅提速（质量取舍由部署方决定）。
    58→ */
    59→export function analysisStageRoute(): LlmStageRoute | undefined {
    60→  return stageRouteFromEnv('LLM_ANALYSIS_ENGINE', 'LLM_ANALYSIS_MODEL');
    61→}
    62→
    63→/** 请求级引擎/模型覆盖（用户自选模型）：随异步上下文传递，避免逐层透传参数 */
    64→export interface LlmOverride {
    65→  engine?: EngineKind;
    66→  model?: string;
    67→  /** 请求用户上下文（authMiddleware 注入，随 LLM 用量埋点落库，支撑按用户统计） */
    68→  userId?: number;
    69→  username?: string;
    70→}
    71→const overrideStore = new AsyncLocalStorage<LlmOverride>();
    72→
    73→/** 在当前请求上下文内设置引擎/模型覆盖（合并式 enterWith：保留已注入的用户上下文等字段） */
    74→export function setLlmOverride(override: LlmOverride): void {
    75→  overrideStore.enterWith({ ...overrideStore.getStore(), ...override });
    76→}
    77→
    78→/** 鉴权后注入请求用户上下文（本次请求异步链内的 LLM 用量埋点均携带该用户） */
    79→export function setLlmUserContext(userId: number, username: string): void {
    80→  overrideStore.enterWith({ ...overrideStore.getStore(), userId, username });
    81→}
    82→
    83→/** 当前上下文的用户上下文（无请求上下文时返回空，如启动期/后台任务） */
    84→export function getLlmUserContext(): { userId?: number; username?: string } {
    85→  const o = overrideStore.getStore();
    86→  return o ? { userId: o.userId, username: o.username } : {};
    87→}
    88→
    89→/** 带请求用户上下文的用量埋点：避免逐调用点手动取 store */
    90→function recordUsage(entry: Parameters<typeof recordLlmUsage>[0]): void {
    91→  const ctx = getLlmUserContext();
    92→  recordLlmUsage({ ...entry, userId: ctx.userId, username: ctx.username });
    93→}
    94→
    95→/** 当前上下文生效的模型名（仅当覆盖引擎与目标通道一致时生效） */
    96→function overrideModel(kind: EngineKind): string | undefined {
    97→  const o = overrideStore.getStore();
    98→  if (!o || !o.model) return undefined;
    99→  return (o.engine || envEngineKind()) === kind ? o.model : undefined;
   100→}
   101→
   102→/** 环境变量级引擎选择（AI_ENGINE 显式 > 密钥存在性） */
   103→function envEngineKind(): EngineKind {
   104→  const explicit = String(process.env.AI_ENGINE || '').toLowerCase();
   105→  if (explicit === 'ollama' || explicit === 'gemini' || explicit === 'qwen') return explicit;
   106→  if (process.env.GEMINI_API_KEY) return 'gemini';
   107→  if (process.env.QWEN_API_KEY) return 'qwen';
   108→  return 'ollama';
   109→}
   110→
   111→function engineKind(): EngineKind {
   112→  return overrideStore.getStore()?.engine || envEngineKind();
   113→}
   114→
   115→export function llmEngineLabel(): string {
   116→  const kind = engineKind();
   117→  if (kind === 'gemini') return 'Gemini API';
   118→  if (kind === 'qwen') return `Qwen ${qwenModel()}`;
   119→  return `Ollama ${llmModel()} @ ${ollamaUrl()}`;
   120→}
   121→
   122→export interface LlmEngineInfo {
   123→  engine: 'ollama' | 'gemini' | 'qwen';
   124→  model: string;
   125→  /** 前端展示标签（不含内网地址） */
   126→  label: string;
   127→}
   128→
   129→/** 供前端按实际使用的模型展示提示信息 */
   130→export function llmEngineInfo(): LlmEngineInfo {
   131→  const kind = engineKind();
   132→  if (kind === 'gemini') return { engine: 'gemini', model: geminiModel(), label: `Gemini ${geminiModel()}` };
   133→  if (kind === 'qwen') return { engine: 'qwen', model: qwenModel(), label: `Qwen ${qwenModel()}` };
   134→  return { engine: 'ollama', model: llmModel(), label: `Ollama ${llmModel()}` };
   135→}
   136→
   137→/** 可选模型目录条目（供前端用户自选） */
   138→export interface ModelOption {
   139→  engine: EngineKind;
   140→  model: string;
   141→  label: string;
   142→  /** 是否为服务端默认引擎/模型 */
   143→  isDefault: boolean;
   144→}
   145→
   146→/** 校验用户提交的模型选择；未提供返回 null，非法返回错误原因 */
   147→export function validateModelSelection(
   148→  engine: unknown,
   149→  model: unknown
   150→): { engine: EngineKind; model: string } | { error: string } | null {
   151→  if (engine === undefined || engine === null || engine === '') return null;
   152→  if (typeof engine !== 'string' || !['ollama', 'gemini', 'qwen'].includes(engine)) {
   153→    return { error: '不支持的模型引擎' };
   154→  }
   155→  if (typeof model !== 'string' || !model.trim() || model.length > 100 || !/^[\w.:\-]+$/.test(model)) {
   156→    return { error: '模型名称不合法' };
   157→  }
   158→  return { engine: engine as EngineKind, model: model.trim() };
   159→}
   160→
   161→/**
   162→ * 当前部署可用的模型目录：
   163→ * - ollama：实时拉取 /api/tags 已安装模型（不可达时回退配置项）
   164→ * - qwen/gemini：已配置密钥时列入（模型为环境配置值）
   165→ */
   166→export async function listAvailableModels(): Promise<ModelOption[]> {
   167→  const def = envEngineKind();
   168→  const defModel = def === 'qwen' ? (process.env.QWEN_MODEL || 'qwen3.8-max') : def === 'gemini' ? GEMINI_MODEL : process.env.LLM_MODEL || 'deepseek-r1:32b';
   169→  const opts: ModelOption[] = [];
   170→
   171→  // Ollama 本地已安装模型（3s 超时，不可达时仅列配置模型）
   172→  let ollamaModels: string[] = [];
   173→  try {
   174→    const controller = new AbortController();
   175→    const timer = setTimeout(() => controller.abort(), 3_000);
   176→    const res = await fetch(`${ollamaUrl()}/api/tags`, { signal: controller.signal });
   177→    clearTimeout(timer);
   178→    if (res.ok) {
   179→      const json: any = await res.json();
   180→      ollamaModels = Array.isArray(json?.models)
   181→        ? json.models.map((m: any) => String(m?.name || '')).filter(Boolean)
   182→        : [];
   183→    }
   184→  } catch {
   185→    // Ollama 不可达：仅当其为默认引擎时列出配置模型
   186→  }
   187→  const ollamaList = ollamaModels.length > 0 ? ollamaModels : [process.env.LLM_MODEL || 'deepseek-r1:32b'];
   188→  for (const name of ollamaList) {
   189→    opts.push({ engine: 'ollama', model: name, label: `Ollama ${name}`, isDefault: def === 'ollama' && name === defModel });
   190→  }
   191→
   192→  if (process.env.QWEN_API_KEY) {
   193→    const m = process.env.QWEN_MODEL || 'qwen3.8-max';
   194→    opts.push({ engine: 'qwen', model: m, label: `Qwen ${m}`, isDefault: def === 'qwen' });
   195→  }
   196→  if (process.env.GEMINI_API_KEY) {
   197→    opts.push({ engine: 'gemini', model: GEMINI_MODEL, label: `Gemini ${GEMINI_MODEL}`, isDefault: def === 'gemini' });
   198→  }
   199→  return opts;
   200→}
   201→
   202→/** 通道层返回：文本 + 可选 token 用量（P2-4 成本埋点，引擎不返回时缺省） */
   203→interface ChannelUsage {
   204→  promptTokens: number;
   205→  completionTokens: number;
   206→}
   207→interface ChannelOutcome {
   208→  text: string;
   209→  usage?: ChannelUsage;
   210→}
   211→
   212→/** 通义千问 OpenAI 兼容通道（百炼按量 / Coding Plan 均适用，端点由 QWEN_URL 决定） */
   213→async function qwenChat(messages: ChatMessage[], formatJson = true, modelOverride?: string): Promise<ChannelOutcome> {
   214→  const controller = new AbortController();
   215→  const timer = setTimeout(() => controller.abort(), qwenTimeoutMs());
   216→
   217→  try {
   218→    const res = await fetch(`${qwenUrl()}/chat/completions`, {
   219→      method: 'POST',
   220→      headers: {
   221→        'Content-Type': 'application/json',
   222→        Authorization: `Bearer ${process.env.QWEN_API_KEY || ''}`,
   223→      },
   224→      signal: controller.signal,
   225→      body: JSON.stringify({
   226→        model: modelOverride || qwenModel(),
   227→        messages,
   228→        stream: false,
   229→        ...(formatJson ? { response_format: { type: 'json_object' } } : {}),
   230→      }),
   231→    });
   232→
   233→    if (!res.ok) {
   234→      const text = await res.text().catch(() => '');
   235→      throw new Error(`Qwen API error: ${res.status} ${text}`);
   236→    }
   237→
   238→    const json: any = await res.json();
   239→    // P2-4 成本埋点：OpenAI 兼容响应带 usage 字段
   240→    const u = json?.usage;
   241→    return {
   242→      text: json.choices?.[0]?.message?.content || '',
   243→      usage: u && (Number(u.prompt_tokens) > 0 || Number(u.completion_tokens) > 0)
   244→        ? { promptTokens: Number(u.prompt_tokens) || 0, completionTokens: Number(u.completion_tokens) || 0 }
   245→        : undefined,
   246→    };
   247→  } catch (err: any) {
   248→    if (err?.name === 'AbortError') {
   249→      throw new Error(`Qwen 推理超时（超过 ${Math.round(qwenTimeoutMs() / 1000)} 秒）`, { cause: err });
   250→    }
   251→    throw err;
   252→  } finally {
   253→    clearTimeout(timer);
   254→  }
   255→}
   256→
   257→async function ollamaChat(messages: ChatMessage[], formatJson = true, modelOverride?: string): Promise<ChannelOutcome> {
   258→  const controller = new AbortController();
   259→  const timer = setTimeout(() => controller.abort(), ollamaTimeoutMs());
   260→
   261→  try {
   262→    const res = await fetch(`${ollamaUrl()}/api/chat`, {
   263→      method: 'POST',
   264→      headers: { 'Content-Type': 'application/json' },
   265→      signal: controller.signal,
   266→      body: JSON.stringify({
   267→        model: modelOverride || llmModel(),
   268→        messages,
   269→        stream: false,
   270→        // 模型常驻 30 分钟，避免连续问答间卸载/重载开销
   271→        keep_alive: '30m',
   272→        ...(formatJson ? { format: 'json' } : {}),
   273→      }),
   274→    });
   275→
   276→    if (!res.ok) {
   277→      const text = await res.text().catch(() => '');
   278→      throw new Error(`Ollama API error: ${res.status} ${text}`);
   279→    }
   280→
   281→    const json: any = await res.json();
   282→    // P2-4 成本埋点：Ollama 返回 prompt_eval_count / eval_count
   283→    const pt = Number(json?.prompt_eval_count) || 0;
   284→    const ct = Number(json?.eval_count) || 0;
   285→    return {
   286→      text: json.message?.content || '',
   287→      usage: pt > 0 || ct > 0 ? { promptTokens: pt, completionTokens: ct } : undefined,
   288→    };
   289→  } catch (err: any) {
   290→    if (err?.name === 'AbortError') {
   291→      throw new Error(`Ollama 推理超时（超过 ${Math.round(ollamaTimeoutMs() / 1000)} 秒）`, { cause: err });
   292→    }
   293→    throw err;
   294→  } finally {
   295→    clearTimeout(timer);
   296→  }
   297→}
   298→
   299→/**
   300→ * 以 JSON 输出模式调用 LLM，返回原始文本（调用方负责 safeParseJson + 结构校验）。
   301→ * history 为已净化的多轮上下文（仅 user 消息，见 L4 历史层）。
   302→ * opts.route：阶段级模型路由（P1-2）；用户请求级自选模型（setLlmOverride）优先于阶段路由。
   303→ */
   304→export async function callLLMJson(system: string, user: string, history: ChatMessage[] = [], opts?: { route?: LlmStageRoute }): Promise<string> {
   305→  const messages: ChatMessage[] = [
   306→    { role: 'system', content: system },
   307→    ...history,
   308→    { role: 'user', content: user },
   309→  ];
   310→
   311→  // 阶段路由仅在用户未自选模型时生效（用户显式选择始终优先）
   312→  const route = overrideStore.getStore()?.model ? undefined : opts?.route;
   313→  const kind: EngineKind = route ? route.engine : engineKind();
   314→  const usedModel = kind === 'ollama' ? route?.model || llmModel() : kind === 'qwen' ? route?.model || qwenModel() : route?.model || geminiModel();
   315→
   316→  // P2-4 成本埋点：统一计时，成功/失败均落库（fire-and-forget）
   317→  const t0 = Date.now();
   318→  try {
   319→    let outcome: ChannelOutcome;
   320→    if (kind === 'ollama') outcome = await ollamaChat(messages, true, route?.model);
   321→    else if (kind === 'qwen') outcome = await qwenChat(messages, true, route?.model);
   322→    else {
   323→      const { GoogleGenAI } = await import('@google/genai');
   324→      const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY! });
   325→      const contents = [
   326→        ...history.map((m) => ({
   327→          role: m.role === 'assistant' ? 'model' : 'user',
   328→          parts: [{ text: m.content }],
   329→        })),
   330→        { role: 'user', parts: [{ text: user }] },
   331→      ];
   332→      const response = await ai.models.generateContent({
   333→        model: route?.model || geminiModel(),
   334→        contents,
   335→        config: {
   336→          systemInstruction: system,
   337→          responseMimeType: 'application/json',
   338→        },
   339→      });
   340→      const um = (response as any)?.usageMetadata;
   341→      outcome = {
   342→        text: response.text || '{}',
   343→        usage: um && (Number(um.promptTokenCount) > 0 || Number(um.candidatesTokenCount) > 0)
   344→          ? { promptTokens: Number(um.promptTokenCount) || 0, completionTokens: Number(um.candidatesTokenCount) || 0 }
   345→          : undefined,
   346→      };
   347→    }
   348→    recordUsage({
   349→      engine: kind,
   350→      model: usedModel,
   351→      channel: 'json',
   352→      promptTokens: outcome.usage?.promptTokens || 0,
   353→      completionTokens: outcome.usage?.completionTokens || 0,
   354→      durationMs: Date.now() - t0,
   355→      ok: true,
   356→    });
   357→    return outcome.text;
   358→  } catch (err) {
   359→    recordUsage({ engine: kind, model: usedModel, channel: 'json', promptTokens: 0, completionTokens: 0, durationMs: Date.now() - t0, ok: false });
   360→    throw err;
   361→  }
   362→}
   363→
   364→/**
   365→ * 以纯文本模式调用 LLM（SQL 解释/优化建议等非结构化输出场景）。
   366→ * 与 callLLMJson 的区别仅是不要求 JSON 输出格式。
   367→ */
   368→export async function callLLMText(system: string, user: string): Promise<string> {
   369→  const kind = engineKind();
   370→  const usedModel = kind === 'ollama' ? llmModel() : kind === 'qwen' ? qwenModel() : geminiModel();
   371→  const t0 = Date.now();
   372→  try {
   373→    let outcome: ChannelOutcome;
   374→    if (kind === 'ollama') {
   375→      outcome = await ollamaChat(
   376→        [
   377→          { role: 'system', content: system },
   378→          { role: 'user', content: user },
   379→        ],
   380→        false
   381→      );
   382→    } else if (kind === 'qwen') {
   383→      outcome = await qwenChat(
   384→        [
   385→          { role: 'system', content: system },
   386→          { role: 'user', content: user },
   387→        ],
   388→        false
   389→      );
   390→    } else {
   391→      const { GoogleGenAI } = await import('@google/genai');
   392→      const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY! });
   393→      const response = await ai.models.generateContent({
   394→        model: geminiModel(),
   395→        contents: [{ role: 'user', parts: [{ text: user }] }],
   396→        config: { systemInstruction: system },
   397→      });
   398→      const um = (response as any)?.usageMetadata;
   399→      outcome = {
   400→        text: response.text || '',
   401→        usage: um && (Number(um.promptTokenCount) > 0 || Number(um.candidatesTokenCount) > 0)
   402→          ? { promptTokens: Number(um.promptTokenCount) || 0, completionTokens: Number(um.candidatesTokenCount) || 0 }
   403→          : undefined,
   404→      };
   405→    }
   406→    recordUsage({
   407→      engine: kind,
   408→      model: usedModel,
   409→      channel: 'text',
   410→      promptTokens: outcome.usage?.promptTokens || 0,
   411→      completionTokens: outcome.usage?.completionTokens || 0,
   412→      durationMs: Date.now() - t0,
   413→      ok: true,
   414→    });
   415→    return outcome.text;
   416→  } catch (err) {
   417→    recordUsage({ engine: kind, model: usedModel, channel: 'text', promptTokens: 0, completionTokens: 0, durationMs: Date.now() - t0, ok: false });
   418→    throw err;
   419→  }
   420→}
   421→
   422→// embedding 模型（Ollama 需已 pull，如 nomic-embed-text；未装时调用方降级为关键词检索）
   423→const embedModel = () => process.env.EMBED_MODEL || 'nomic-embed-text';
   424→// 千问 embedding 模型（Coding Plan 端点可能不支持，失败时调用方自动降级关键词粗排）
   425→const qwenEmbedModel = () => process.env.QWEN_EMBED_MODEL || 'text-embedding-v4';
   426→
   427→// embedding 短 TTL 缓存：同一问题的 query 向量在圈表精排与知识库检索间复用，重试/重复提问不再重复调用
   428→const EMBED_CACHE_TTL_MS = 10 * 60 * 1000;
   429→const EMBED_CACHE_MAX = 256;
   430→const embedCache = new Map<string, { v: number[]; exp: number }>();
   431→
   432→function embedCacheGet(key: string): number[] | null {
   433→  const hit = embedCache.get(key);
   434→  if (!hit) return null;
   435→  if (hit.exp <= Date.now()) {
   436→    embedCache.delete(key);
   437→    return null;
   438→  }
   439→  return hit.v;
   440→}
   441→
   442→function embedCacheSet(key: string, v: number[]): void {
   443→  if (embedCache.size >= EMBED_CACHE_MAX) {
   444→    const oldest = embedCache.keys().next().value;
   445→    if (oldest !== undefined) embedCache.delete(oldest);
   446→  }
   447→  embedCache.set(key, { v, exp: Date.now() + EMBED_CACHE_TTL_MS });
   448→}
   449→
   450→/** 供测试清空 embedding 缓存 */
   451→export function clearEmbeddingCacheForTest(): void {
   452→  embedCache.clear();
   453→}
   454→
   455→/**
   456→ * 文本 → 向量。Ollama 走 /api/embeddings，Qwen 走 /embeddings，Gemini 走 embedContent。
   457→ * role 区分查询/文档：nomic-embed-text 需加 search_query:/search_document: 指令前缀，
   458→ * 否则短问题与长文档相似度被压平、区分度下降。
   459→ * 失败（未装 embedding 模型 / 网络异常）时抛错，由调用方降级处理。
   460→ */
   461→export async function callEmbedding(text: string, role?: 'query' | 'document'): Promise<number[]> {
   462→  let input = String(text || '').slice(0, 2000);
   463→  if (!input.trim()) throw new Error('embedding 输入为空');
   464→  if (role && embedModel().startsWith('nomic')) {
   465→    input = `${role === 'query' ? 'search_query' : 'search_document'}: ${input}`;
   466→  }
   467→
   468→  const kind = engineKind();
   469→
