    12→const INJECTION_PATTERNS: RegExp[] = [
    13→  /ignore\s+(all\s+)?(the\s+)?(previous|above|prior)\s+(instructions?|prompts?|rules?)/i,
    14→  /disregard\s+(all\s+)?(the\s+)?(previous|above|prior)\s+(instructions?|prompts?)/i,
    15→  /forget\s+(all\s+)?(the\s+)?(previous|above)\s+(instructions?|rules?)/i,
