    88→export function filterSensitiveColumns<T extends TableLike>(schema: T[]): {
    89→  schema: T[];
    90→  removed: string[];
    91→} {
    92→  const removed: string[] = [];
    93→  const filtered = (Array.isArray(schema) ? schema : []).map((table) => {
    94→    const columns = Array.isArray(table.columns) ? table.columns : [];
    95→    const kept = columns.filter((c) => {
