    97→      if (SENSITIVE_COLUMN_PATTERN.test(text)) {
    98→        removed.push(`${table.name}.${c?.name || ''}`);
    99→        return false;
   100→      }
   101→      return true;
   102→    });
   103→    return { ...table, columns: kept };
   104→  });
   105→  return { schema: filtered, removed };
   106→}
