     1→/**
     2→ * 限流器（按 IP 计数）。供 server.ts 与各个路由模块共享，避免循环依赖。
     3→ * 默认内存滑动窗口（行为不变）；配置 REDIS_URL 后走 Redis 固定分钟窗口 INCR，
     4→ * 多实例部署时限流计数全局共享。
     5→ */
     6→import type express from 'express';
     7→import { getStateStore, isRedisEnabled } from './stateStore';
     8→
     9→const RATE_LIMIT_WINDOW_MS = 60_000;
    10→// ESM import 提升会使模块级 process.env 读取早于 dotenv.config()，须惰性读取
    11→const rateLimitMax = () => Number(process.env.RATE_LIMIT_MAX) || 30;
    12→const requestLog = new Map<string, number[]>();
    13→
    14→export async function rateLimiter(req: express.Request, res: express.Response, next: express.NextFunction) {
    15→  const key = req.ip || 'unknown';
    16→  const now = Date.now();
    17→
    18→  // Redis 模式：固定分钟窗口原子计数（多实例共享）；存储异常 fail-closed 拒绝
    19→  if (isRedisEnabled()) {
    20→    try {
    21→      const bucket = Math.floor(now / RATE_LIMIT_WINDOW_MS);
    22→      const n = await getStateStore().incrWindow(`rl:${key}:${bucket}`, Math.ceil(RATE_LIMIT_WINDOW_MS / 1000) + 10);
    23→      if (n > rateLimitMax()) {
    24→        return res.status(429).json({ error: '请求过于频繁，请稍后再试。' });
    25→      }
    26→      return next();
    27→    } catch {
    28→      return res.status(429).json({ error: '请求过于频繁，请稍后再试。' });
    29→    }
    30→  }
    31→
    32→  const windowStart = now - RATE_LIMIT_WINDOW_MS;
    33→  const hits = (requestLog.get(key) || []).filter((t) => t > windowStart);
    34→
    35→  if (hits.length >= rateLimitMax()) {
    36→    return res.status(429).json({ error: '请求过于频繁，请稍后再试。' });
    37→  }
    38→
    39→  hits.push(now);
    40→  requestLog.set(key, hits);
    41→  next();
    42→}
    43→
    44→// Periodically prune stale rate-limit entries（仅内存模式生效）
    45→setInterval(() => {
    46→  if (isRedisEnabled()) return;
    47→  const windowStart = Date.now() - RATE_LIMIT_WINDOW_MS;
    48→  for (const [key, hits] of requestLog.entries()) {
    49→    const fresh = hits.filter((t) => t > windowStart);
    50→    if (fresh.length === 0) requestLog.delete(key);
    51→    else requestLog.set(key, fresh);
    52→  }
    53→}, RATE_LIMIT_WINDOW_MS).unref();
    54→

