     1→/**
     2→ * P1-1 语义指标层：管理员登记结构化业务指标定义（名称/同义词/聚合口径/归属表/固定过滤），
     3→ * 问数阶段一按「问题命中指标名/同义词 → 模板化注入口径」生成 SQL，
     4→ * 保证同一指标全系统口径一致，消除 LLM 每次自由发挥导致的指标漂移。
     5→ * 指标文本仅注入 prompt（不直接拼接 SQL），生成结果仍过安全执行层校验。
     6→ */
     7→import type { RowDataPacket, ResultSetHeader } from 'mysql2';
     8→import { getPool } from './db';
     9→
    10→export interface MetricDefinition {
    11→  id?: number;
    12→  dataSourceId: string;
    13→  /** 指标名（数据源内唯一），如「有效客户数」 */
    14→  name: string;
    15→  /** 同义词列表，参与问数命中匹配 */
    16→  aliases: string[];
    17→  /** 口径说明（面向人的解释） */
    18→  description: string;
    19→  /** 聚合表达式，如 COUNT(DISTINCT id) / SUM(amount) */
    20→  expr: string;
    21→  /** 归属表名（须与 Schema 表名一致） */
    22→  tableName: string;
    23→  /** 固定过滤条件（WHERE 片段，可为空），如 status = 'active' */
    24→  filters: string;
    25→  status: 'ACTIVE' | 'DISABLED';
    26→  createdBy?: string;
    27→}
    28→
    29→const MAX_METRICS_PER_DS = 200;
    30→
    31→/** 校验并规整指标输入；非法时返回 error 说明（路由层据此 400） */
    32→export function sanitizeMetricInput(input: any): { ok: true; metric: Omit<MetricDefinition, 'id'> } | { ok: false; error: string } {
    33→  const dataSourceId = typeof input?.dataSourceId === 'string' ? input.dataSourceId.trim() : '';
    34→  const name = typeof input?.name === 'string' ? input.name.trim() : '';
    35→  const expr = typeof input?.expr === 'string' ? input.expr.trim() : '';
    36→  const tableName = typeof input?.tableName === 'string' ? input.tableName.trim() : '';
    37→  const filters = typeof input?.filters === 'string' ? input.filters.trim() : '';
    38→  const description = typeof input?.description === 'string' ? input.description.trim().slice(0, 300) : '';
    39→  const aliases = Array.isArray(input?.aliases)
    40→    ? input.aliases.filter((a: any) => typeof a === 'string' && a.trim()).map((a: string) => a.trim().slice(0, 50)).slice(0, 10)
    41→    : [];
    42→
    43→  if (!dataSourceId) return { ok: false, error: '缺少 dataSourceId' };
    44→  if (!name || name.length > 50) return { ok: false, error: '指标名必填且不超过 50 字' };
    45→  if (!expr || expr.length > 200) return { ok: false, error: '聚合表达式必填且不超过 200 字' };
    46→  if (/;\s*\S/.test(expr) || /;\s*\S/.test(filters)) return { ok: false, error: '表达式/过滤条件不允许多语句' };
    47→  if (!/^[A-Za-z_][\w]*$/.test(tableName)) return { ok: false, error: '归属表名必须是合法标识符' };
    48→  if (filters.length > 300) return { ok: false, error: '固定过滤条件不超过 300 字' };
    49→  if (aliases.some((a: string) => a === name)) return { ok: false, error: '同义词不能与指标名相同' };
    50→
    51→  return {
    52→    ok: true,
    53→    metric: { dataSourceId, name, aliases, description, expr, tableName, filters, status: input?.status === 'DISABLED' ? 'DISABLED' : 'ACTIVE' },
    54→  };
    55→}
    56→
    57→/** 问题命中匹配：指标名或任一同义词作为子串出现在问题中即命中（确定性、零延迟） */
    58→export function matchMetrics(query: string, metrics: MetricDefinition[]): MetricDefinition[] {
    59→  const q = String(query || '');
    60→  if (!q.trim()) return [];
    61→  return metrics.filter((m) => {
    62→    if (q.includes(m.name)) return true;
    63→    return m.aliases.some((a) => a && q.includes(a));
    64→  });
    65→}
    66→
    67→/** 命中指标的模板化 prompt 段：逐条给出口径，强制阶段一遵循 */
    68→export function buildMetricPrompt(hits: MetricDefinition[]): string {
    69→  if (hits.length === 0) return '';
    70→  const lines = hits.map((m) => {
    71→    const filter = m.filters ? `，固定过滤条件：WHERE ${m.filters}` : '';
    72→    const alias = m.aliases.length > 0 ? `（同义词：${m.aliases.join('、')}）` : '';
    73→    const desc = m.description ? `，口径说明：${m.description}` : '';
    74→    return `- ${m.name}${alias} = ${m.expr}，基于表 ${m.tableName}${filter}${desc}`;
    75→  });
    76→  return `【语义指标层定义】（管理员登记的权威口径，问题涉及以下指标时必须严格使用给定的聚合表达式、归属表与固定过滤条件，禁止自行变更口径）:\n${lines.join('\n')}\n\n`;
    77→}
    78→
    79→// ---------- CRUD（routes/metrics.ts 调用） ----------
    80→
    81→function rowToMetric(r: any): MetricDefinition {
    82→  let aliases: string[] = [];
    83→  try {
    84→    const parsed = JSON.parse(String(r.aliases_json || '[]'));
    85→    aliases = Array.isArray(parsed) ? parsed.filter((a: any) => typeof a === 'string') : [];
    86→  } catch {
    87→    aliases = [];
    88→  }
    89→  return {
    90→    id: Number(r.id),
    91→    dataSourceId: String(r.data_source_id),
    92→    name: String(r.name),
    93→    aliases,
    94→    description: String(r.description || ''),
    95→    expr: String(r.expr),
    96→    tableName: String(r.table_name),
    97→    filters: String(r.filters || ''),
    98→    status: r.status === 'DISABLED' ? 'DISABLED' : 'ACTIVE',
    99→    createdBy: String(r.created_by || ''),
   100→  };
   101→}
   102→
   103→export async function listMetrics(dataSourceId: string): Promise<MetricDefinition[]> {
   104→  const [rows] = await getPool().query<RowDataPacket[]>(
   105→    'SELECT * FROM metric_definitions WHERE data_source_id = ? ORDER BY created_at DESC, id DESC LIMIT 500',
   106→    [dataSourceId]
   107→  );
   108→  return rows.map(rowToMetric);
   109→}
   110→
   111→/** 问数链路专用：仅取启用指标（上限保护，失败由调用方 catch 降级） */
   112→export async function loadActiveMetrics(dataSourceId: string): Promise<MetricDefinition[]> {
   113→  const [rows] = await getPool().query<RowDataPacket[]>(
   114→    "SELECT * FROM metric_definitions WHERE data_source_id = ? AND status = 'ACTIVE' ORDER BY id ASC LIMIT ?",
   115→    [dataSourceId, MAX_METRICS_PER_DS]
   116→  );
   117→  return rows.map(rowToMetric);
   118→}
   119→
   120→export async function createMetric(metric: Omit<MetricDefinition, 'id'>, createdBy: string): Promise<{ ok: true; id: number } | { ok: false; error: string }> {
   121→  const pool = getPool();
   122→  const [dup] = await pool.query<RowDataPacket[]>(
   123→    'SELECT id FROM metric_definitions WHERE data_source_id = ? AND name = ? LIMIT 1',
   124→    [metric.dataSourceId, metric.name]
   125→  );
   126→  if (dup.length > 0) return { ok: false, error: '同名指标已存在' };
   127→  const [result] = await pool.query<ResultSetHeader>(
   128→    `INSERT INTO metric_definitions (data_source_id, name, aliases_json, description, expr, table_name, filters, status, created_by)
   129→     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
   130→    [metric.dataSourceId, metric.name, JSON.stringify(metric.aliases), metric.description, metric.expr, metric.tableName, metric.filters, metric.status, createdBy]
   131→  );
   132→  return { ok: true, id: result.insertId };
   133→}
   134→
   135→export async function updateMetric(id: number, metric: Omit<MetricDefinition, 'id' | 'dataSourceId'>): Promise<{ ok: true } | { ok: false; error: string; notFound?: boolean }> {
   136→  const pool = getPool();
   137→  const [existing] = await pool.query<RowDataPacket[]>('SELECT data_source_id FROM metric_definitions WHERE id = ? LIMIT 1', [id]);
   138→  if (existing.length === 0) return { ok: false, error: '指标不存在', notFound: true };
   139→  const dataSourceId = String(existing[0].data_source_id);
   140→  const [dup] = await pool.query<RowDataPacket[]>(
   141→    'SELECT id FROM metric_definitions WHERE data_source_id = ? AND name = ? AND id <> ? LIMIT 1',
   142→    [dataSourceId, metric.name, id]
   143→  );
   144→  if (dup.length > 0) return { ok: false, error: '同名指标已存在' };
   145→  await pool.query(
   146→    `UPDATE metric_definitions SET name = ?, aliases_json = ?, description = ?, expr = ?, table_name = ?, filters = ?, status = ? WHERE id = ?`,
   147→    [metric.name, JSON.stringify(metric.aliases), metric.description, metric.expr, metric.tableName, metric.filters, metric.status, id]
   148→  );
   149→  return { ok: true };
   150→}
   151→
   152→export async function deleteMetric(id: number): Promise<boolean> {
   153→  const [result] = await getPool().query<ResultSetHeader>('DELETE FROM metric_definitions WHERE id = ?', [id]);
   154→  return result.affectedRows > 0;
   155→}
   156→

