    57→/** 问题命中匹配：指标名或任一同义词作为子串出现在问题中即命中（确定性、零延迟） */
    58→export function matchMetrics(query: string, metrics: MetricDefinition[]): MetricDefinition[] {
    59→  const q = String(query || '');
    60→  if (!q.trim()) return [];
    61→  return metrics.filter((m) => {
    62→    if (q.includes(m.name)) return true;
    63→    return m.aliases.some((a) => a && q.includes(a));
    64→  });
    65→}
    66→
    67→/** 命中指标的模板化 prompt 段：逐条给出口径，强制阶段一遵循 */
    68→export function buildMetricPrompt(hits: MetricDefinition[]): string {
