    72→    const alias = m.aliases.length > 0 ? `（同义词：${m.aliases.join('、')}）` : '';
    73→    const desc = m.description ? `，口径说明：${m.description}` : '';
    74→    return `- ${m.name}${alias} = ${m.expr}，基于表 ${m.tableName}${filter}${desc}`;
    75→  });
    76→  return `【语义指标层定义】（管理员登记的权威口径，问题涉及以下指标时必须严格使用给定的聚合表达式、归属表与固定过滤条件，禁止自行变更口径）:\n${lines.join('\n')}\n\n`;
    77→}
