    79→// ---------- CRUD（routes/metrics.ts 调用） ----------
    80→
    81→function rowToMetric(r: any): MetricDefinition {
    82→  let aliases: string[] = [];
    83→  try {
    84→    const parsed = JSON.parse(String(r.aliases_json || '[]'));
    85→    aliases = Array.isArray(parsed) ? parsed.filter((a: any) => typeof a === 'string') : [];
    86→  } catch {
