    90→    id: Number(r.id),
    91→    dataSourceId: String(r.data_source_id),
    92→    name: String(r.name),
    93→    aliases,
    94→    description: String(r.description || ''),
    95→    expr: String(r.expr),
    96→    tableName: String(r.table_name),
    97→    filters: String(r.filters || ''),
    98→    status: r.status === 'DISABLED' ? 'DISABLED' : 'ACTIVE',
    99→    createdBy: String(r.created_by || ''),
   100→  };
   101→}
   102→
   103→export async function listMetrics(dataSourceId: string): Promise<MetricDefinition[]> {
   104→  const [rows] = await getPool().query<RowDataPacket[]>(
   105→    'SELECT * FROM metric_definitions WHERE data_source_id = ? ORDER BY created_at DESC, id DESC LIMIT 500',
   106→    [dataSourceId]
   107→  );
   108→  return rows.map(rowToMetric);
   109→}
   110→
   111→/** 问数链路专用：仅取启用指标（上限保护，失败由调用方 catch 降级） */
   112→export async function loadActiveMetrics(dataSourceId: string): Promise<MetricDefinition[]> {
   113→  const [rows] = await getPool().query<RowDataPacket[]>(
   114→    "SELECT * FROM metric_definitions WHERE data_source_id = ? AND status = 'ACTIVE' ORDER BY id ASC LIMIT ?",
   115→    [dataSourceId, MAX_METRICS_PER_DS]
   116→  );
   117→  return rows.map(rowToMetric);
   118→}
   119→
   120→export async function createMetric(metric: Omit<MetricDefinition, 'id'>, createdBy: string): Promise<{ ok: true; id: number } | { ok: false; error: string }> {
   121→  const pool = getPool();
   122→  const [dup] = await pool.query<RowDataPacket[]>(
   123→    'SELECT id FROM metric_definitions WHERE data_source_id = ? AND name = ? LIMIT 1',
   124→    [metric.dataSourceId, metric.name]
   125→  );
   126→  if (dup.length > 0) return { ok: false, error: '同名指标已存在' };
   127→  const [result] = await pool.query<ResultSetHeader>(
   128→    `INSERT INTO metric_definitions (data_source_id, name, aliases_json, description, expr, table_name, filters, status, created_by)
   129→     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
   130→    [metric.dataSourceId, metric.name, JSON.stringify(metric.aliases), metric.description, metric.expr, metric.tableName, metric.filters, metric.status, createdBy]
   131→  );
   132→  return { ok: true, id: result.insertId };
   133→}
   134→
   135→export async function updateMetric(id: number, metric: Omit<MetricDefinition, 'id' | 'dataSourceId'>): Promise<{ ok: true } | { ok: false; error: string; notFound?: boolean }> {
   136→  const pool = getPool();
   137→  const [existing] = await pool.query<RowDataPacket[]>('SELECT data_source_id FROM metric_definitions WHERE id = ? LIMIT 1', [id]);
   138→  if (existing.length === 0) return { ok: false, error: '指标不存在', notFound: true };
   139→  const dataSourceId = String(existing[0].data_source_id);
   140→  const [dup] = await pool.query<RowDataPacket[]>(
   141→    'SELECT id FROM metric_definitions WHERE data_source_id = ? AND name = ? AND id <> ? LIMIT 1',
   142→    [dataSourceId, metric.name, id]
   143→  );
   144→  if (dup.length > 0) return { ok: false, error: '同名指标已存在' };
   145→  await pool.query(
   146→    `UPDATE metric_definitions SET name = ?, aliases_json = ?, description = ?, expr = ?, table_name = ?, filters = ?, status = ? WHERE id = ?`,
   147→    [metric.name, JSON.stringify(metric.aliases), metric.description, metric.expr, metric.tableName, metric.filters, metric.status, id]
   148→  );
   149→  return { ok: true };
   150→}
   151→
   152→export async function deleteMetric(id: number): Promise<boolean> {
   153→  const [result] = await getPool().query<ResultSetHeader>('DELETE FROM metric_definitions WHERE id = ?', [id]);
   154→  return result.affectedRows > 0;
