    11→
    12→export const CHUNK_SIZE = 400;
    13→export const CHUNK_OVERLAP = 80;
    14→export const TOP_K_CHUNKS = 4;
    15→/** 单文档最多入选块数：防止大字典文档占满槽位，保证口径/指南类文档有注入机会 */
