    18→ * 防止字段字典类文档在向量相似度上全面占优、挤掉口径规则 */
    19→export const GUIDED_DOC_KEYWORDS = ['口径', '指南', '速查', '规则', '枚举'];
    20→/** 保留槽位选块时的词法混合权重：向量分 + 权重×归一 bigram，
    21→ * 避免分块边界把正答块排在同文档其他块之后 */
    22→export const GUIDED_BIGRAM_WEIGHT = 0.15;
    23→
    24→/** 按段落优先、定长兜底切块，相邻块保留 overlap 以防语义被截断 */
    25→export function chunkText(text: string, chunkSize = CHUNK_SIZE, overlap = CHUNK_OVERLAP): string[] {
    26→  const src = String(text || '').trim();
    27→  if (!src) return [];
    28→
    29→  // 先按换行切段落，逐段合并到 chunkSize 以内
    30→  const paras = src.split(/\n+/).map((p) => p.trim()).filter(Boolean);
    31→  const merged: string[] = [];
    32→  let buf = '';
    33→  for (const p of paras) {
    34→    if (buf && (buf.length + 1 + p.length) > chunkSize) {
    35→      merged.push(buf.trim());
    36→      buf = buf.slice(-overlap) + '\n' + p;
    37→    } else {
    38→      buf = buf ? `${buf}\n${p}` : p;
    39→    }
    40→  }
    41→  if (buf.trim()) merged.push(buf.trim());
    42→
    43→  // 超长单块强制按步长切
    44→  const out: string[] = [];
    45→  const step = Math.max(1, chunkSize - overlap);
    46→  for (const c of merged) {
    47→    if (c.length <= chunkSize) {
    48→      out.push(c);
    49→      continue;
    50→    }
    51→    for (let i = 0; i < c.length; i += step) {
    52→      out.push(c.slice(i, i + chunkSize));
    53→    }
    54→  }
    55→  return out.filter((c) => c.trim().length > 0);
    56→}
    57→
    58→/** 余弦相似度：向量维度不一致或零向量时返回 0 */
    59→export function cosineSimilarity(a: number[], b: number[]): number {
    60→  if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length || a.length === 0) return 0;
    61→  let dot = 0;
    62→  let na = 0;
    63→  let nb = 0;
    64→  for (let i = 0; i < a.length; i++) {
    65→    dot += a[i] * b[i];
    66→    na += a[i] * a[i];
    67→    nb += b[i] * b[i];
    68→  }
    69→  if (na === 0 || nb === 0) return 0;
    70→  return dot / (Math.sqrt(na) * Math.sqrt(nb));
    71→}
