    85→ */
    86→export function rankChunks(
    87→  question: string,
    88→  chunks: KnowledgeChunk[],
    89→  questionEmbedding: number[] | null,
    90→  topK = TOP_K_CHUNKS,
    91→  maxPerDoc = MAX_CHUNKS_PER_DOC,
    92→  reserveGuided = true
    93→): KnowledgeChunk[] {
    94→  const scored = chunks
    95→    .map((c) => {
    96→      const useVector =
    97→        Array.isArray(questionEmbedding) &&
    98→        Array.isArray(c.embedding) &&
    99→        c.embedding.length === questionEmbedding.length;
