   103→      return { c, score };
   104→    })
   105→    .filter((s) => s.score > 0)
   106→    .sort((a, b) => b.score - a.score);
   107→  const out: KnowledgeChunk[] = [];
   108→  const picked = new Set<KnowledgeChunk>();
   109→  const perDoc = new Map<string, number>();
   110→  const push = (c: KnowledgeChunk) => {
   111→    out.push(c);
   112→    picked.add(c);
   113→    perDoc.set(c.title, (perDoc.get(c.title) || 0) + 1);
   114→  };
