   137→/** 将检索到的片段格式化为阶段一 prompt 注入块；无结果返回空串 */
   138→export function formatKnowledgeSnippets(chunks: KnowledgeChunk[]): string {
   139→  if (chunks.length === 0) return '';
   140→  const lines = chunks.map((c) => `- [${c.title}] ${c.text.replace(/\s+/g, ' ').trim()}`);
