   145→
   146→/** 登记一篇业务知识文档：切块 + 逐块 embedding（失败置空走关键词降级），返回块数。
   147→ * 传入 existingDocId 时复用该 docId（编辑场景，调用方需先删除旧块）。 */
   148→export async function saveKnowledgeDoc(
   149→  dataSourceId: string,
   150→  title: string,
   151→  content: string,
   152→  createdBy: string,
   153→  existingDocId?: string
   154→): Promise<{ docId: string; chunkCount: number }> {
