   170→    );
   171→  }
   172→  return { docId, chunkCount: chunks.length };
   173→}
   174→
   175→/** 检索与问题最相关的知识片段并格式化为 prompt 块（任何异常降级为空串，不阻断问数） */
   176→export async function retrieveKnowledgeSnippets(
   177→  dataSourceId: string,
   178→  question: string,
   179→  topK = TOP_K_CHUNKS
   180→): Promise<string> {
   181→  try {
   182→    const [rows] = await getPool().query(
   183→      'SELECT title, chunk_text, embedding_json FROM knowledge_base WHERE data_source_id = ?',
   184→      [dataSourceId]
   185→    );
   186→    const chunks: KnowledgeChunk[] = (rows as any[]).map((r) => {
   187→      let embedding: number[] | null = null;
   188→      try {
   189→        embedding = r.embedding_json ? JSON.parse(r.embedding_json) : null;
   190→      } catch {
   191→        embedding = null;
   192→      }
   193→      return { title: String(r.title || ''), text: String(r.chunk_text || ''), embedding: Array.isArray(embedding) ? embedding : null };
   194→    });
   195→    if (chunks.length === 0) return '';
   196→
   197→    let questionEmbedding: number[] | null = null;
   198→    try {
   199→      questionEmbedding = await callEmbedding(question, 'query');
   200→    } catch {
   201→      questionEmbedding = null;
   202→    }
   203→    return formatKnowledgeSnippets(rankChunks(question, chunks, questionEmbedding, topK));
   204→  } catch {
   205→    return '';
   206→  }
   207→}
