    30→    const colDesc = String(c?.description || '');
    31→    if (!colDesc) continue;
    32→    // 列中文名整词出现在问题中（如「客户类型」），强相关
    33→    if (colDesc.length >= 2 && question.includes(colDesc)) score += 3;
