    96→
    97→async function embedTable(table: any): Promise<number[] | null> {
    98→  const digest = tableDigest(table);
    99→  if (!digest.trim()) return null;
   100→  const key = `${String(table?.name || '')}::${digest.slice(0, 200)}`;
   101→  const hit = tableEmbeddingCache.get(key);
