   121→ * 表多时先粗排到 2×maxTables 再精排，控制 embedding 调用次数；
   122→ * embedding 全部不可用时等价于纯关键词版（行为不退化）。
   123→ */
   124→export async function selectRelevantTablesAsync(
   125→  schema: any[],
   126→  question: string,
   127→  maxTables: number = MAX_TABLES_IN_PROMPT
   128→): Promise<any[]> {
   129→  const tables = Array.isArray(schema) ? schema.filter(Boolean) : [];
   130→  if (tables.length <= maxTables) return tables;
   131→
   132→  const q = String(question || '');
   133→  const preScored = tables.map((t, idx) => ({ t, idx, kw: tableScore(t, q) }));
   134→  // 粗排候选：表特别多时取 2×maxTables，其余全量参与精排
   135→  const candidateCount = tables.length > maxTables * 2 ? maxTables * 2 : tables.length;
   136→  const candidates = [...preScored].sort((a, b) => b.kw - a.kw || a.idx - b.idx).slice(0, candidateCount);
   137→
   138→  let qVec: number[] | null = null;
   139→  try {
   140→    qVec = await callEmbedding(q, 'query');
   141→    if (!Array.isArray(qVec) || qVec.length === 0) qVec = null;
   142→  } catch {
   143→    qVec = null;
   144→  }
   145→  if (!qVec) return pickByKeyword(tables, candidates, maxTables);
   146→
   147→  const finalScored = await Promise.all(
   148→    candidates.map(async (c) => {
   149→      const tVec = await embedTable(c.t);
   150→      const sim = tVec ? Math.max(0, cosineSim(qVec as number[], tVec)) : 0;
   151→      return { ...c, score: c.kw + sim * 12 };
   152→    })
   153→  );
   154→  finalScored.sort((a, b) => b.score - a.score || a.idx - b.idx);
   155→  const picked = new Set(finalScored.slice(0, maxTables).map((s) => s.idx));
   156→  return tables.filter((_, idx) => picked.has(idx));
   157→}
   158→
   159→function pickByKeyword(tables: any[], candidates: { idx: number }[], maxTables: number): any[] {
   160→  const picked = new Set(candidates.slice(0, maxTables).map((s) => s.idx));
   161→  return tables.filter((_, idx) => picked.has(idx));
   162→}
