   122→ * embedding 全部不可用时等价于纯关键词版（行为不退化）。
   123→ */
   124→export async function selectRelevantTablesAsync(
   125→  schema: any[],
   126→  question: string,
   127→  maxTables: number = MAX_TABLES_IN_PROMPT
