   142→  } catch {
   143→    qVec = null;
   144→  }
   145→  if (!qVec) return pickByKeyword(tables, candidates, maxTables);
   146→
   147→  const finalScored = await Promise.all(
   148→    candidates.map(async (c) => {
   149→      const tVec = await embedTable(c.t);
   150→      const sim = tVec ? Math.max(0, cosineSim(qVec as number[], tVec)) : 0;
   151→      return { ...c, score: c.kw + sim * 12 };
   152→    })
   153→  );
   154→  finalScored.sort((a, b) => b.score - a.score || a.idx - b.idx);
   155→  const picked = new Set(finalScored.slice(0, maxTables).map((s) => s.idx));
   156→  return tables.filter((_, idx) => picked.has(idx));
   157→}
   158→
   159→function pickByKeyword(tables: any[], candidates: { idx: number }[], maxTables: number): any[] {
   160→  const picked = new Set(candidates.slice(0, maxTables).map((s) => s.idx));
   161→  return tables.filter((_, idx) => picked.has(idx));
   162→}
