   236→/**
   237→ * P1-3 行级权限：把带行过滤的表在 AST 中包裹为过滤子查询
   238→ * （FROM clients → FROM (SELECT * FROM clients WHERE <谓词>) AS clients），
   239→ * 递归覆盖子查询/UNION 内的引用。谓词解析失败或 AST 回写失败均 fail-closed 拒绝，
   240→ * 安全优先于可用性（此时问数降级演示模式，不泄露受限行）。
   241→ * rowFilters 键为小写实际表名；SQL 未引用受控表时原样返回。
   242→ */
   243→export function injectRowFilters(
   244→  sql: string,
   245→  rowFilters: Record<string, string>,
   246→  dialect: SqlDialect = 'mysql'
   247→): SqlSafetyResult {
   248→  const lower: Record<string, string> = {};
   249→  for (const [name, pred] of Object.entries(rowFilters)) {
   250→    if (name && pred) lower[name.toLowerCase()] = pred;
   251→  }
   252→  if (Object.keys(lower).length === 0) return { ok: true, sql };
   253→
   254→  const stripped = stripCommentsAndStrings(sql);
   255→  const refs = extractTableRefs(stripped.replace(/;+\s*$/, ''));
   256→  if (!refs.some((r) => lower[r])) return { ok: true, sql };
   257→
   258→  const opt = { database: dialect === 'pg' ? 'PostgreSQL' : 'MySQL' };
   259→  try {
   260→    const parsed: any = astParser.astify(sql, opt);
   261→
   262→    // 谓词 → 派生表 expr：解析 `SELECT * FROM (SELECT * FROM t WHERE pred) AS t`
   263→    // 直接复用解析产物（而非手工拼 AST），保证 sqlify 回写时派生表带括号；
   264→    // 谓词非法自然抛错，fail-closed。
   265→    const wrappedOf = (table: string, pred: string): any => {
   266→      const helper: any = astParser.astify(`SELECT * FROM (SELECT * FROM ${table} WHERE ${pred}) AS ${table}`, opt);
   267→      const h = Array.isArray(helper) ? helper[0] : helper;
   268→      const item = h && Array.isArray(h.from) ? h.from[0] : null;
   269→      if (!item || !item.expr) throw new Error('谓词解析失败');
   270→      return item.expr;
   271→    };
   272→
   273→    const wrapFrom = (from: any): void => {
   274→      if (!Array.isArray(from)) return;
   275→      for (const item of from) {
   276→        if (!item) continue;
   277→        // 派生表（FROM (SELECT ...)）递归下钻：5.x 为 { ast, parentheses } 包裹层，旧版直接是 select 节点
   278→        if (item.expr && typeof item.expr === 'object') {
   279→          const inner = item.expr.ast && typeof item.expr.ast === 'object' ? item.expr.ast : item.expr;
   280→          walkNode(inner);
   281→        }
   282→        const tableName = typeof item.table === 'string' ? item.table : '';
   283→        const pred = tableName ? lower[tableName.toLowerCase()] : undefined;
   284→        if (!pred) continue;
   285→        // 未显式起别名时补上原表名，保证外层列引用不变
   286→        if (!item.as) item.as = tableName;
   287→        item.expr = wrappedOf(tableName, pred);
   288→        item.table = null;
   289→        item.db = null;
   290→      }
   291→    };
   292→    const walkNode = (node: any): void => {
   293→      if (!node || typeof node !== 'object') return;
   294→      if (Array.isArray(node)) {
   295→        node.forEach(walkNode);
   296→        return;
   297→      }
   298→      if (node.type === 'select') {
   299→        wrapFrom(node.from);
   300→        // WHERE/HAVING 等表达式中的子查询（IN (SELECT ...)、EXISTS 等）
   301→        walkExprSubqueries(node.where);
   302→        walkExprSubqueries(node.having);
   303→        // UNION/UNION ALL 链（node-sql-parser 5.x 用 _next 链 + set_op）
   304→        if (node._next) walkNode(node._next);
   305→      }
   306→    };
   307→    const walkExprSubqueries = (expr: any): void => {
   308→      if (!expr || typeof expr !== 'object') return;
   309→      if (Array.isArray(expr)) {
   310→        expr.forEach(walkExprSubqueries);
   311→        return;
   312→      }
   313→      if (expr.ast && typeof expr.ast === 'object') walkNode(expr.ast);
   314→      walkExprSubqueries(expr.left);
   315→      walkExprSubqueries(expr.right);
   316→      if (expr.value !== undefined) walkExprSubqueries(expr.value);
   317→      if (Array.isArray(expr.args)) walkExprSubqueries(expr.args);
   318→    };
   319→
   320→    walkNode(Array.isArray(parsed) ? parsed[0] : parsed);
   321→    const rewritten = astParser.sqlify(parsed, opt);
   322→    if (typeof rewritten !== 'string' || !rewritten.trim()) {
   323→      return { ok: false, reason: '行级权限注入失败，已拒绝该查询' };
   324→    }
   325→    return { ok: true, sql: rewritten };
   326→  } catch {
   327→    return { ok: false, reason: '行级权限注入失败，已拒绝该查询' };
   328→  }
   329→}
