   331→// ---- 数据源连接池（按数据源 ID 缓存；mysql 走 mysql2，PG 系走 pg 驱动） ----
   332→type DsPoolEntry = { dialect: 'mysql'; pool: mysql.Pool } | { dialect: 'pg'; pool: pg.Pool };
   333→const dsPools = new Map<string, DsPoolEntry>();
   334→
   335→/** 数据源配置变更/删除后调用，使连接池失效 */
   336→export function invalidateExecutorPool(dataSourceId?: string): void {
   337→  if (dataSourceId) {
   338→    const entry = dsPools.get(dataSourceId);
   339→    dsPools.delete(dataSourceId);
   340→    entry?.pool.end().catch(() => undefined);
   341→  } else {
   342→    for (const [id, entry] of dsPools) {
   343→      dsPools.delete(id);
   344→      entry.pool.end().catch(() => undefined);
   345→    }
   346→  }
