   349→export interface ExecResult {
   350→  rows: Record<string, any>[];
   351→  rowCount: number;
   352→  /** true 表示结果被 MAX_ROWS 截断 */
   353→  truncated: boolean;
   354→  finalSql: string;
   355→  /** P1-3：true 表示 AST 解析失败放行（正则白名单兜底），供路由层审计 */
   356→  astFallback?: boolean;
