   359→export type ExecOutcome =
   360→  | { ok: true; result: ExecResult }
   361→  | { ok: false; reason: string };
   362→
   363→/** 读取数据源连接配置（含密码，仅服务端使用；dataVersion 指纹探测亦复用） */
   364→export async function loadDataSourceConfig(dataSourceId: string): Promise<{ type: string; config: any } | null> {
   365→  const [rows] = await getPool().query('SELECT type, config_json FROM data_sources WHERE id = ?', [dataSourceId]);
   366→  const ds = (rows as any[])[0];
   367→  if (!ds) return null;
   368→  let config = ds.config_json;
   369→  if (typeof config === 'string') {
   370→    try { config = JSON.parse(config); } catch { config = {}; }
   371→  }
   372→  config = config || {};
   373→  // P0：落库密码为 AES-256-GCM 密文，连接前解密（明文存量透传）
   374→  if (config.password) config.password = decryptSecret(String(config.password));
   375→  return { type: String(ds.type || ''), config };
   376→}
   377→
   378→export function getDsPool(dataSourceId: string, dialect: SqlDialect, config: any): DsPoolEntry {
   379→  let entry = dsPools.get(dataSourceId);
   380→  if (!entry) {
   381→    if (dialect === 'pg') {
   382→      // PostgreSQL / Greenplum：同属 PG 协议。超时由服务端 statement_timeout 强制，
   383→      // 连接级超时用 connectionTimeoutMillis；只读保障以 SELECT-only 校验 + 单语句为主防线。
   384→      entry = {
   385→        dialect: 'pg',
   386→        pool: new pg.Pool({
   387→          host: config?.host || '127.0.0.1',
   388→          port: Number(config?.port) || 5432,
   389→          user: config?.username || 'postgres',
   390→          password: config?.password || '',
   391→          database: config?.database || undefined,
   392→          max: 3,
   393→          connectionTimeoutMillis: CONNECT_TIMEOUT_MS,
   394→          statement_timeout: QUERY_TIMEOUT_MS,
   395→        }),
   396→      };
   397→    } else {
   398→      entry = {
   399→        dialect: 'mysql',
   400→        pool: mysql.createPool({
   401→          host: config?.host || '127.0.0.1',
   402→          port: Number(config?.port) || 3306,
   403→          user: config?.username || 'root',
   404→          password: config?.password || '',
   405→          database: config?.database || undefined,
   406→          connectionLimit: 3,
   407→          connectTimeout: CONNECT_TIMEOUT_MS,
   408→          multipleStatements: false,
   409→        }),
   410→      };
   411→    }
   412→    dsPools.set(dataSourceId, entry);
   413→  }
   414→  return entry;
   415→}
   416→
   417→/**
   418→ * 校验并执行 SQL。dataSourceId 必须是支持真实执行的数据源类型
   419→ * （mysql / postgresql / greenplum），否则返回 UNSUPPORTED_DS_TYPE（调用方走演示模式）。
   420→ * rowFilters：P1-3 行级权限（实际表名 → 谓词），白名单校验通过后 AST 强制注入。
   421→ */
   422→export async function executeSafeSql(
   423→  dataSourceId: string,
   424→  rawSql: unknown,
   425→  allowedTables: { name: string; columns?: { name: string }[] }[],
   426→  sensitiveColumns: string[] = [],
   427→  maxRows: number = MAX_ROWS,
   428→  rowFilters: Record<string, string> = {}
   429→): Promise<ExecOutcome> {
   430→  const ds = await loadDataSourceConfig(dataSourceId);
   431→  if (!ds) return { ok: false, reason: '数据源不存在' };
   432→  const dialect = dialectOfDsType(ds.type);
   433→  if (!dialect) {
   434→    return { ok: false, reason: 'UNSUPPORTED_DS_TYPE' };
   435→  }
   436→
   437→  const check = validateSelectSql(rawSql, allowedTables, sensitiveColumns, dialect, maxRows);
   438→  if (check.ok !== true) return { ok: false, reason: check.reason };
   439→
   440→  // P1-3 行级权限：校验通过后、执行前强制注入（注入失败 fail-closed）
   441→  const injected = injectRowFilters(check.sql, rowFilters, dialect);
   442→  if (injected.ok !== true) return { ok: false, reason: injected.reason };
   443→  const finalSql = injected.sql;
   444→
   445→  try {
   446→    const entry = getDsPool(dataSourceId, dialect, ds.config);
   447→    let list: Record<string, any>[];
   448→    if (entry.dialect === 'pg') {
   449→      // pg 驱动：超时由建池时的 statement_timeout 承担，结果在 result.rows
   450→      const result = await entry.pool.query(finalSql);
   451→      list = Array.isArray(result.rows) ? result.rows : [];
   452→    } else {
   453→      const [rows] = await entry.pool.query({ sql: finalSql, timeout: QUERY_TIMEOUT_MS });
   454→      list = (Array.isArray(rows) ? rows : []) as Record<string, any>[];
   455→    }
   456→    return {
   457→      ok: true,
   458→      result: {
   459→        rows: list.slice(0, maxRows),
   460→        rowCount: list.length,
   461→        truncated: list.length > maxRows,
   462→        finalSql,
   463→        astFallback: check.astFallback === true,
   464→      },
   465→    };
   466→  } catch (err: any) {
   467→    return { ok: false, reason: `SQL 执行失败：${String(err?.message || err).slice(0, 200)}` };
   468→  }
   469→}
